ns.data = {
  client = "forever",
  sections = {
    { id = "beasts", title = "Beasts", type = "Beast" },
    { id = "dragonkin", title = "Dragonkin", type = "Dragonkin" },
    { id = "demons", title = "Demons", type = "Demon" },
    { id = "elementals", title = "Elementals", type = "Elemental" },
    { id = "undead", title = "The Undead", type = "Undead" },
    { id = "giants", title = "Giants", type = "Giant" },
    { id = "machines", title = "Machines", type = "Mechanical" },
    { id = "peoples", title = "Humanoids", type = "Humanoid" },
    { id = "oddities", title = "Oddities", type = "NotSpecified" },
  },
  families = {
    { id = "wolves", title = "Wolves", section = "beasts", note = { "Wolves are the first lesson of the wild for most travellers, and the most persistent. They run in packs from the snows of Dun Morogh to the pine slopes of Alterac, through the timber of Elwynn and the hills of Silverpine, and they follow the same law everywhere: the weak at the back, the strong at the front, and anything slower than the pack is supper.", "The worgs of the north are larger and fouler-tempered than their southern kin, and the black ravagers of Duskwood hunt in numbers that should give anyone pause. Coyotes are the same animal grown lean in dry country.", "A wolf alone is a nuisance. A howl answered from three directions is a warning. Learn the difference early." } },
    { id = "great-cats", title = "Great Cats", section = "beasts", note = { "The great cats are the quietest killers in this book. The nightsabers of Teldrassil, the frostsabers of Winterspring, the panthers and tigers of Stranglethorn and the mountain lions of the Alterac foothills all share one habit: you rarely see them until they have already decided about you.", "The night elves ride the sabers and honour them; the trolls of the south hunt the jungle cats for their pelts and their courage. Either way, a cat that has marked you will stalk you a long time, and it will choose the moment, not you.", "Watch the long grass. Then watch it again." } },
    { id = "spiders", title = "Spiders", section = "beasts", note = { "Spiders have adapted to nearly every dark corner of Azeroth: the mines under Elwynn, the Webwood of Teldrassil, the tombs of Duskwood, the caves of the Wetlands and the Swamp of Sorrows. Their sizes run from a hand's width to a horse's, and their venoms from a sting to a death.", "Most of them do not hunt so much as wait. A web across a cave mouth, a burrow at the edge of a path, and the patience of something that can go a season without eating. The matriarchs are the ones to fear: larger, older, and surrounded by their young.", "Carry a torch, and keep your eyes on the ceiling as well as the floor." } },
    { id = "bears", title = "Bears", section = "beasts", note = { "Bears are the great solitary foragers of the forests, and they are only peaceful until you stand between one and something it wants. The black bears of Dun Morogh, Loch Modan and the Wetlands, the grizzlies of Silverpine, the thistle bears of Darkshore, the ironfurs of Feralas, the shardtooths of Winterspring: each forest grows its own, and the colder ones grow them meaner.", "The furbolgs revere them, and the druids take their shape. A traveller would do better simply to give them room. A sow with cubs will not distinguish between a careless step and an attack.", "They sleep long in winter. They do not wake gently." } },
    { id = "boars", title = "Boars", section = "beasts", note = { "Boars are the plain, stubborn fighters of the wild, found wherever there is soft earth to root in: the stonetusks of Elwynn, the crag boars of Dun Morogh, the goretusks of Westfall and the mottled boars of Durotar's dry gullies.", "They are not clever, and they do not need to be. A boar charges first and reconsiders never. The farmers of Westfall curse them for the turnips they dig up; the cooks of every inn bless them for the same reason.", "The quilboar of the Barrens claim the boar as their sacred kin. Having watched both, I can see the family resemblance." } },
    { id = "crocolisks", title = "Crocolisks", section = "beasts", note = { "Crocolisks are ancient things, long-jawed and armoured, which have outlasted empires by the simple method of lying still in warm water and eating whatever comes to drink. They haunt the lochs of Khaz Modan, the bogs of the Wetlands, the rivers of Stranglethorn and the shores of Dustwallow.", "A crocolisk on the bank looks asleep. It is not. It can cover the distance to a careless traveller faster than seems decent for something so heavy.", "Their hides make fine leather, and their meat is better than it has any right to be. Neither is worth losing a leg over." } },
    { id = "carrion-birds", title = "Carrion Birds", section = "beasts", note = { "The carrion birds are the patient ones: vultures, buzzards and condors circling over the Barrens, the Badlands and the Thousand Needles, waiting for the land to do their killing for them. The fleshrippers of Westfall have grown bolder since the farms emptied, and will not always wait.", "They are a sign worth reading. A ring of them in the sky means something below has died or is about to, and sometimes it is wise to find out what before you walk into it.", "The rocs of the far south are another matter: great birds of prey that hunt living game, and treat a traveller as such." } },
    { id = "crabs", title = "Crabs", section = "beasts", note = { "Crabs crowd every shore of Azeroth, from the beaches of Westfall and Darkshore to the reefs of the Barrens and the Stranglethorn coast. Sand crawlers, surf crawlers, tide crawlers: the names change with the coast, the habits do not.", "They are armoured, short-tempered and sideways, and they defend a patch of sand with a ferocity out of all proportion to its value. The meat inside is sweet, which is why the fishermen of every coast keep their pots baited.", "Approach from the front; the claws are slower than the legs. Or leave them be, which is wiser still." } },
    { id = "gorillas", title = "Gorillas", section = "beasts", note = { "The great apes of Stranglethorn, Feralas and Un'Goro live in troops on the high ground, led by the largest silverback, and they are a good deal cleverer than the jungle trolls who hunt them like to admit. The gorillas of the Mistvale and the thunderers of the jungle beat their chests and the trees around them before a fight, which gives fair warning to anyone who listens.", "They are not cruel, only territorial, and a troop's patience ends at its feeding grounds.", "There are tales of kings among them, larger than any troll and treated with a respect a troll chieftain might envy." } },
    { id = "raptors", title = "Raptors", section = "beasts", note = { "The raptors are hunters to the bone: fast, clever, and bred, it seems, for nothing but the chase. They run in hunting parties through the Barrens, the Wetlands, the Arathi Highlands, Stranglethorn and Dustwallow, and the trolls of the jungle have tamed them for war since before human memory.", "A raptor that sees you will call others. Its screech is not a challenge; it is a summons.", "The bloodtalons of Durotar and the sunscales of the Barrens are the smallest of their kind, and the first that most young Horde warriors learn to fear. They are not the last." } },
    { id = "tallstriders", title = "Tallstriders", section = "beasts", note = { "The tallstriders are long-legged, long-necked birds of the open plains, and the plainstriders of Mulgore and the Barrens are the most familiar sight of the grasslands after the kodo. They are harmless enough until cornered, and then they kick hard enough to break a shield.", "The tauren hunt them for their meat and feathers, with the thanks the Earth Mother asks of them; the night elves of Darkshore and Felwood know a forest cousin, the foreststrider.", "Their eggs are prized. Their mothers are aware of this." } },
    { id = "scorpids", title = "Scorpids", section = "beasts", note = { "Scorpids thrive where little else does: the red canyons of Durotar, the dust of the Barrens, Desolace and the Thousand Needles, the deserts of Tanaris and Silithus, the cinders of the Burning Steppes. Hard-shelled, many-legged and armed with a tail that carries a venom worth respecting, they are the land's own answer to drought.", "They hunt in the cool of evening and bury themselves in the heat of the day, so that a traveller often walks among more of them than he knows.", "The orcs value their shells and their stings. Shake out your boots in the morning." } },
    { id = "turtles", title = "Turtles", section = "beasts", note = { "The turtles of Azeroth come in two kinds: the snapjaws of the rivers and lakes, which bite, and the great sea turtles of the southern coasts, which are mostly too large to need to. Both are older than they look and slower than they seem only until they decide otherwise.", "The snapjaw's beak can take a finger cleanly. The surf gliders of Tanaris drift the warm coastal waters like islands with opinions, and the coralshell tortoises of Azshara are not much quicker.", "Their shells are prized by armourers and their patience by philosophers. Admire them from the bank." } },
    { id = "bats", title = "Bats", section = "beasts", note = { "Bats roost wherever there is dark and quiet: the caves of Tirisfal, the crypts and barrows of the Plaguelands, the thorn-tunnels of the Razorfen. The duskbats of Tirisfal are the first many of the Forsaken meet on waking, and a fair sample of the rest.", "They hunt by sound in the dark, and they come in clouds when disturbed. The plaguebats of the east are another thing altogether: carriers of the Scourge's sickness on the wing.", "Keep your mouth shut when you walk under a roost. You will thank me." } },
    { id = "hyenas", title = "Hyenas", section = "beasts", note = { "Hyenas are the scavengers of the hot country: the Barrens, Desolace, the Thousand Needles, Tanaris and the Blasted Lands. They laugh as they hunt, which is unsettling the first time and no less so the tenth, and they hunt in packs that will follow a wounded traveller for miles.", "The centaurs keep them as war dogs, and the gnolls have something of their temper. The blisterpaws of Tanaris and the snickerfangs of the Blasted Lands are the leanest and most vicious of their kind.", "They prefer the easy meal. Do not be one." } },
    { id = "owls", title = "Owls", section = "beasts", note = { "The owls of Azeroth are watchful, solitary hunters of the night forests: the strigids of Teldrassil, the ironbeaks of Felwood, the great owls of Winterspring. The night elves hold them sacred to Elune, and the moonkin who walk upright among them share that blessing in a stranger form.", "An owl sees you long before you see it, and most will let you pass. The corrupted owls of Felwood will not, and they strike from above, out of the dark, without a sound.", "If you hear wings and nothing else, duck." } },
    { id = "wind-serpents", title = "Wind Serpents", section = "beasts", note = { "Wind serpents are winged snakes of the warm skies, gliding over the cliffs of the Thousand Needles, the Barrens, Feralas, Dustwallow and the jungles of the south. They spit lightning, which no honest snake should be able to do, and they nest high where few can follow.", "The trolls of Zul'Gurub keep a darker kind, the sons of their blood god, which are best not discussed before supper.", "From below they are beautiful. From closer, they are mostly teeth." } },
    { id = "basilisks", title = "Basilisks", section = "beasts", note = { "Basilisks are heavy, low-slung lizards with stony hides and stonier stares, found in the hot and barren places: the hills of Stranglethorn, Tanaris, Desolace, the Thousand Needles, the Blasted Lands. Their gaze is said to turn flesh to stone, and while I have not seen it happen, I have seen enough of their victims stiff and grey to keep my eyes down.", "Crystals grow on the backs of the older ones, which tells you something about how long they lie still.", "The Explorers' League would like very much to know what they eat. Mostly, it appears, explorers." } },
    { id = "kodos", title = "Kodos", section = "beasts", note = { "The kodo are the great grey beasts of the plains, slow, enormous and sure-footed, and the tauren have walked beside them for as long as there have been tauren. Herds cross the Barrens and Desolace; the Horde rides and harnesses them; caravans trust them where no horse would go.", "When a kodo grows too old to walk with the herd, it goes alone to die in the graveyard of Desolace, and nobody, tauren or scholar, can tell me how it knows the way.", "A frightened kodo is a landslide with legs. Do not frighten one." } },
    { id = "rams-and-goats", title = "Rams and Goats", section = "beasts", note = { "The rams of Khaz Modan are mountain beasts through and through: thick-fleeced, sure-hooved and possessed of opinions about anyone on their slope. The dwarves have ridden them for generations, and in Alterac Valley the Stormpike tame the valley's wild rams to ride them to war.", "A wild ram will stand its ground and then charge it, horns first. It is the dwarven temperament in four legs, and I say so with affection.", "Their wool is fine, their milk better, and their sense of balance makes a dwarf jealous." } },
    { id = "sharks-and-fish", title = "Sharks and Fish", section = "beasts", note = { "Below the waves is another bestiary entirely, and this page covers only the part of it that bites: the sharks of the southern seas, the threshers of Darkshore and Dustwallow, the frenzies that boil in the lochs and rivers at the smell of blood, and the snappers of the warm coasts.", "A swimmer bleeding into the water is a dinner bell. The frenzies of the Barrens' oases and Loch Modan are small, but they come in hundreds.", "If you must swim, swim fast and swim clean. If you must fish, fish from a boat." } },
    { id = "thunder-lizards", title = "Thunder Lizards", section = "beasts", note = { "The thunder lizards are great lumbering beasts of the Barrens and Desolace, heavy-boned and crackling with a storm of their own making. When they fight, lightning runs over their hides, and the air around them tastes of it.", "The tauren say they were born of the storms over the plains, and having stood near one in a temper I am inclined to believe it.", "They graze peacefully enough, in small herds. The cliff stormers of Stonetalon are smaller, quicker and far less peaceful." } },
    { id = "great-saurians", title = "Devilsaurs and the Beasts of Un'Goro", section = "beasts", note = { "In Un'Goro Crater the world has kept a corner of its youth, and the beasts in it are older than any kingdom: the devilsaurs, great two-legged hunters whose tread you feel before you see them; the stegodons with their plated backs; the diemetradons of the hot springs; the pterrordaxes wheeling overhead.", "Nothing in the crater fears a traveller, because nothing in the crater has needed to. A devilsaur walks where it likes, and everything else moves.", "The Marshal expedition learned this the hard way. Read their notes before you go, and keep to the high ground." } },
    { id = "stags-and-steeds", title = "Stags, Steeds and Grazers", section = "beasts", note = { "The grazers of the wild are many and mostly peaceful: the zhevras and giraffes of the Barrens, the stags and coursers of Ashenvale and Stonetalon, the mosshoofs of Azshara.", "They are the game of every hunter, from tauren to troll to the Kaldorei who thank the forest for each one taken. Most will flee rather than fight; a stag in the rut, or a mare with a foal, may not.", "The stagwings of Feralas and Azshara fly, which is not a sentence I expected to write in a natural history." } },
    { id = "snakes", title = "Snakes", section = "beasts", note = { "Snakes are everywhere a traveller does not look: under rocks, in long grass, in the warm stones of the south. Most of the small ones in this book are harmless; the ones that are not, are very much not.", "The deviate snakes of the Wailing Caverns are twisted by whatever is wrong in that place, and the serpents of Zul'Gurub belong to the blood god's temples and behave accordingly.", "Walk heavily, and the snakes will usually leave before you arrive. That is the whole of my advice, and it has served me well." } },
    { id = "chimaeras", title = "Chimaeras", section = "beasts", note = { "A chimaera is a winged, two-headed beast with a long neck, a longer tail and a temper to match, and it breathes a venom that burns. They nest in the high places of Kalimdor, and in the cold of Winterspring a white-furred kind hunts over the snow.", "Both heads watch, which makes them very hard to surprise, and both heads bite.", "The chimaeroks of Feralas are the largest of their kind, and the most dangerous creatures in that forest that are not ogres." } },
    { id = "hydras", title = "Hydras", section = "beasts", note = { "Hydras are many-headed serpents of the deep waters, and every legend that says cutting off one head grows two is, as far as I can tell, a slander. One head is quite enough trouble.", "The Mystlash of Ashenvale's and Felwood's waters and the hydras deep in Maraudon rise when anything comes too near. The Sandfury trolls of Tanaris worship a greater one, Gahz'rilla, in their sacred pool.", "If the water ahead is unusually calm, take the long way round." } },
    { id = "worms-and-grubs", title = "Worms and Grubs", section = "beasts", note = { "The burrowers and grubs of Azeroth are the earth's cleaners: maggots in the dead fields of the Plaguelands, borers in the rock of Desolace and the sands of Tanaris, grubs under every corpse left too long. Most are small; some are not.", "The rock worms of the deep places can swallow a dwarf, as more than one prospector of the League has learned too late to report.", "They are not hunters so much as appetites. That does not make them any safer to stand on." } },
    { id = "insects", title = "Insects", section = "beasts", note = { "Beyond the silithid, which have their own pages, Azeroth's insects are mostly beneath a traveller's notice: beetles, flies, the scarabs that scuttle in the dry places. The scarabs of the south are another matter, large enough to fight and old enough in their habits to seem deliberate.", "They gather around the dead, and in Zul'Farrak they swarm in the shadow of the Sandfury's temples, where few travellers stop to study them.", "Watch the scarabs. They are smaller than the silithid, and they come from the same deserts." } },
    { id = "birds", title = "Birds of the High Places", section = "beasts", note = { "The great birds of the high places are lords of the cliffs: the wyverns of Stonetalon, Feralas and the Thousand Needles, the thunderhawks of the Barrens, the hippogryphs of Azshara and Feralas, and the wild gryphons of the Hillsbrad hills that no rider has yet taken in hand.", "The wyverns and hippogryphs carry the riders of the Horde and the night elves; their wild kin carry nobody, and defend their nests against anything that climbs.", "The firebirds of Tanaris do not look like any bird I know, and they are hot to stand near." } },
    { id = "yetis", title = "Yetis", section = "beasts", note = { "Yetis are great shaggy brutes of the cold mountains and caves: the hills of Alterac, the ice caves of Winterspring and the high valleys of Feralas. They are stronger than any bear and more stubborn than any dwarf.", "They live in families in deep caves, and they come out hungry. A yeti's roar in a cave carries a long way and summons the rest.", "The goblins of Everlook have found uses for their hides and their horns. The yetis have found uses for the goblins." } },
    { id = "wendigos", title = "Wendigos", section = "beasts", note = { "The wendigos of Dun Morogh are great shaggy creatures of the snow, cousins of the yeti, living in the caves of the Grizzled Den and coming out when hunger drives them. They are strong enough to break a young dwarf in two, which is why the mountaineers teach their recruits to read wendigo tracks before anything else.", "They hunt in numbers, and they are cleverer than they look.", "There is an old one in the deepest cave, the dwarves say, and they do not say much more about him." } },
    { id = "other-beasts", title = "Other Beasts", section = "beasts", note = { "Not every beast fits a family. This page holds the rest: the solitary oddities, the named old monsters of a valley, the creatures too strange or too rare to have kin in this book.", "Many of them are the subject of a hunter's story or a farmer's curse: a beast that killed a herd, a creature no one can trap, a thing seen once at dusk and never again.", "If you have met one, you will know it. Write it down; the League will want to hear." } },
    { id = "black-dragonflight", title = "The Black Dragonflight", section = "dragonkin", note = { "The black dragonflight belongs to Deathwing, the Aspect who betrayed his kind, and his children carry on his work. Onyxia keeps her lair and her brood in the Wyrmbog of Dustwallow; Nefarian rules from the top of Blackrock Spire, where he breeds dragons of every colour together for his own ends.", "Their whelps nest in the Burning Steppes, the Badlands and Redridge, and their dragonspawn walk on two legs with blade and spell. The drakes and wyrmkin guard their masters' lairs.", "A black whelp is a nuisance. Everything above it on this page is a danger to kingdoms." } },
    { id = "green-dragonflight", title = "The Green Dragonflight", section = "dragonkin", note = { "The green dragons are Ysera's, the Dreamer's, guardians of the Emerald Dream, and something has gone wrong with them. Some of Ysera's flight are lost in nightmares: Eranikus over the sunken temple, the dragonkin at the great trees of Duskwood, the Hinterlands, Feralas and Ashenvale.", "Their whelps and wyrmkin dream as they fight, and the Nightmare dreams through them.", "If a green dragon speaks to you of sleep, do not listen too closely." } },
    { id = "blue-dragonflight", title = "The Blue Dragonflight", section = "dragonkin", note = { "The blue dragons are Malygos's, guardians of magic, and they watch over the arcane wherever it pools: in Azshara, where the Highborne left their treasures, and in the ice caves of Mazthoril in Winterspring.", "They are scholars as much as warriors, and suspicious of every mortal who carries a spellbook. The cobalt dragonkin of Winterspring guard their lair with spells as well as claws.", "Azuregos, in Azshara, will tell you he is only protecting what belongs to his flight. He will tell you while he fights you." } },
    { id = "red-dragonflight", title = "The Red Dragonflight", section = "dragonkin", note = { "The red dragons are Alexstrasza's, the Life-Binder's, and for years the Dragonmaw orcs held their queen captive at Grim Batol and used her children as beasts of war. She was freed, but some of her dragonkin have never left the mountain, and they guard its halls fiercely.", "Red whelps are still seen in the Wetlands and the hills nearby, and the red flight's dragonspawn and wyrmkin keep Grim Batol shut to all comers.", "They are not the enemies the black flight is. They are only very tired of being taken prisoner." } },
    { id = "faerie-dragons", title = "Faerie Dragons", section = "dragonkin", note = { "Faerie dragons are small, quick, brightly coloured dragonkin of the old forests of Feralas and Ashenvale, more mischief than menace. They blink in and out of sight and they drain magic from anyone careless enough to cast near them.", "The druids think kindly of them, as creatures of the Dream's edge. The deviate kind of the Wailing Caverns has been twisted by whatever is wrong in that place.", "They will mostly leave you alone. Spellcasters, keep your distance." } },
    { id = "bronze-dragonflight", title = "The Bronze Dragonflight", section = "dragonkin", note = { "The bronze dragons are Nozdormu's, the Timeless One's, and they guard the paths of time from their caverns in Tanaris. Few are ever seen outside them; those that are, are usually in mortal shape, and usually on business they will not explain.", "They remember the war against the insects of Ahn'Qiraj, a thousand years ago, as if it were yesterday. For them, perhaps, it was.", "A corrupted bronze whelp is a sad and dangerous thing: a fragment of a flight that is not supposed to be able to go wrong." } },
    { id = "other-dragonkin", title = "Other Dragonkin", section = "dragonkin", note = { "Not every dragon, whelp or dragonspawn can be put in its flight with any confidence. Lone whelps, strays, the dragonkin of mixed blood bred in Blackrock Spire, and creatures that carry a dragon's shape without a dragon's lineage are recorded here.", "A whelp away from its flight is usually lost, hungry and dangerous out of all proportion to its size.", "Where you meet a stray, look around for the rest of the family. Dragons rarely come alone." } },
    { id = "satyrs", title = "Satyrs", section = "demons", note = { "The satyrs were night elves once, Highborne who served the Burning Legion in the war ten thousand years ago, and Sargeras remade them for it: horned, hoofed, clawed, demons in all but birth. Their first was Xavius, Queen Azshara's counsellor.", "They haunt the night elves' forests still, in Darkshore, Ashenvale, Felwood, Azshara and Desolace, corrupting whatever they touch: trees sicken, water turns and beasts go mad around their camps.", "The night elves kill them on sight. Having seen what they do to a forest, I understand why." } },
    { id = "burning-legion", title = "The Burning Legion", section = "demons", note = { "The Burning Legion is an army of demons from beyond the world, and it has come for Azeroth twice in force, and once more through the orcs it corrupted. It never entirely leaves. Its servants hold the Blasted Lands around the dead Dark Portal, haunt Desolace's Mannoroc Coven, Ashenvale's Demon Fall Canyon and the poisoned woods of Felwood, and answer to warlocks wherever warlocks gather.", "Felhounds that eat magic, infernals that fall from the sky, felguards and doomguard, imps, succubi and dreadlords: the Legion's ranks are as varied as the worlds it has conquered.", "No demon in this book is native to Azeroth. All of them would like to be its masters." } },
    { id = "fire-elementals", title = "Fire Elementals", section = "elementals", note = { "Fire elementals are living flame, and they serve Ragnaros, the Firelord, who was woken under Blackrock Mountain more than two hundred years ago. They walk the Searing Gorge and the Burning Steppes, the Molten Core and Un'Goro's volcano, and anywhere a warlock or shaman has called one up and lost hold of it.", "They do not hate you. They simply burn, and you are flammable.", "Water and frost will do you more good against them than steel. A cool head, as ever, helps." } },
    { id = "water-elementals", title = "Water Elementals", section = "elementals", note = { "Water elementals are rarer than their fiery cousins on land, and usually seen where something has gone wrong: a spring fouled by corruption, a mage's summoning broken loose, or the servants of the Hydraxian Waterlords on their island off Azshara, at war with the Firelord's kind.", "They move like a wave breaking, and they hit like one.", "The befouled ones of Ashenvale were once clean springs. That is worth remembering when you wonder why the druids are so angry." } },
    { id = "earth-elementals", title = "Earth Elementals", section = "elementals", note = { "Earth elementals are stone given will: rock elementals in the Badlands and the Burning Steppes, the stone keepers of Uldaman, rumblers and obsidian elementals in the Searing Gorge and the Steppes. Some are wild spirits of the land; some were made, long ago, to guard the works of the titans.", "They are slow to anger and very hard to stop once angry. Blades blunt on them and arrows bounce.", "The stone keepers of Uldaman are of most interest to the League, and I will say only that they are not pleased to see us." } },
    { id = "air-elementals", title = "Air Elementals", section = "elementals", note = { "Air elementals are storms with intent: dust devils over the Barrens and Westfall, whirlwinds in Desolace and Silithus, cyclones that walk the high places. In Silithus the Twilight's Hammer calls up their lords, which is as bad an idea as it sounds.", "They are hard to see, hard to hit and easy to underestimate, until one lifts you off your feet.", "Prince Thunderaan, a lord of the air, lost his essence to the Firelord long ago, and what is left of him is a story for another page." } },
    { id = "living-plants", title = "Living Plants and Ancients", section = "elementals", note = { "Some of Azeroth's forests fight back. Timberlings and treants, lashers and creepers, the ancients of the night elves' woods and the sprites that dance among them: plants with will, and sometimes with malice.", "Many of them were gentle once. The satyrs' corruption, the Legion's taint and the poisons of the Plaguelands have turned whole groves against the travellers who walk them. The swamp creatures of the Wetlands, Dustwallow and the Swamp of Sorrows are another kind: things of mud and rot that walk.", "The druids will tell you which can be saved. Listen to them before you burn anything." } },
    { id = "blighted-elementals", title = "Blighted Elementals", section = "elementals", note = { "Blighted elementals are the earth and water of Azeroth gone wrong: tar beasts rising from Un'Goro's pits, plague monstrosities of the Eastern Plaguelands, the irradiated horrors and fallout of Gnomeregan, and the toxic and entropic horrors of Darkshore and Felwood.", "They are what is left when a land is poisoned long enough to stand up and walk. Their touch carries the sickness that made them.", "Wash after fighting them. Wash twice." } },
    { id = "oozes", title = "Oozes and Slimes", section = "elementals", note = { "Oozes, slimes and sludges collect wherever there is filth and damp: in Dustwallow's bogs, the fens of the Wetlands and the Hinterlands, the swamps of Sorrows, the radiation of Gnomeregan and the poisoned waters of the Plaguelands and Felwood. They are less creatures than appetites with a shape.", "They dissolve what they swallow, armour included, and they are harder to hurt than anything without a shape has a right to be.", "Do not step in anything that moves. It is a good rule in general and a vital one here." } },
    { id = "other-elementals", title = "Other Elementals", section = "elementals", note = { "This page holds the elementals that no single element claims: lords and exiles of mixed nature, spirits of the land too strange to name, constructs animated by elemental power, and the odd servant of a summoner long dead.", "Many are found alone, guarding something or waiting for someone. Some are the masters of the others on these pages.", "Approach each as its own question. Elementals are not, on the whole, interested in conversation." } },
    { id = "scourge", title = "The Scourge", section = "undead", note = { "The Scourge is the army of the Lich King: the dead of Lordaeron, raised by the plague and bound to his will. Skeletons and ghouls, zombies and abominations, the spirits of the plague's victims and the necromancers' constructs fill the Plaguelands, Tirisfal, the Scholomance and Stratholme, and reach as far as the Razorfen Downs.", "They do not tire, they do not fear, and they do not stop. Each one was someone, once.", "The Forsaken, the Argent Dawn and the Scarlet Crusade all fight them. The Scourge does not mind which." } },
    { id = "restless-spirits", title = "Ghosts and Restless Spirits", section = "undead", note = { "Not every ghost in Azeroth serves the Scourge. Some are spirits who never found rest: the Highborne who haunt their ruined towers in Darkshore and Azshara, the drowned and the murdered, the warriors who fell far from home and wander still.", "Some are only sad. Some are angry, and the anger is all that is left of them. A few will speak, if you listen.", "The League records them with care. They are, after all, the oldest witnesses we have." } },
    { id = "other-undead", title = "Other Undead", section = "undead", note = { "The undead on this page are neither the Lich King's soldiers nor simple ghosts: the cursed, the risen by other hands, the dead of Duskwood's dark woods, the murdered who would not lie down, and the servants of necromancers who answer to no king.", "Many have a story, and some of those stories end badly for whoever disturbs them.", "Duskwood's dead in particular repay a visit to the town historian before a visit to the graveyard." } },
    { id = "giants", title = "Giants", section = "giants", note = { "The giants of Azeroth are old beyond reckoning: the sea giants who stride the shores of Desolace, Feralas and Tanaris, the cliff giants of Azshara and Feralas, the frost giants of Winterspring, and the earth's own colossi in Uldaman and Maraudon.", "Some say the titans made them to shape the world. Whatever their origin, they are slow to notice travellers and slower to forget one who has annoyed them.", "A giant's footstep is a small earthquake. Its fist is a large one." } },
    { id = "machines", title = "Golems and Machines", section = "machines", note = { "The machines of this page were made by mortal hands, mostly gnomish and goblin: harvest golems gone rogue in the fields of Westfall, the shredders of Stonetalon, the war constructs of Gnomeregan's mad mekgineer and the Dark Irons' golems.", "They do not think, and that is what makes them dangerous: a machine does what it was built to do long after its maker has stopped wanting it to.", "Most of them have an off switch. Finding it under fire is the difficulty." } },
    { id = "kobolds", title = "Kobolds", section = "peoples", note = { "Kobolds are small, rat-faced diggers of the tunnels, and they are everywhere there is earth to dig: the mines of Elwynn and Westfall, the hills above Loch Modan, the Arathi Highlands and the canyons of Thousand Needles. Each wears a candle on its head, and will fight harder for that candle than for its life.", "Alone they are cowards; in numbers they are a plague. Miners curse them, farmers lose cattle to them, and every young soldier of Stormwind learns to fight on them.", "\"You no take candle!\" is the only thing most travellers ever hear one say. It is, I have found, the whole of their philosophy." } },
    { id = "gnolls", title = "Gnolls", section = "peoples", note = { "Gnolls are hyena-men, tall, lean and quarrelsome, living in packs wherever there are farms with poor walls: the Riverpaw of Elwynn and Westfall, the Redridge and Shadowhide packs, the Mosshide of the Wetlands, the Rot Hide of Silverpine, the Palemane of Mulgore, the Woodpaw of Feralas.", "They follow whoever is strongest and fight among themselves when no one is. Hogger of Elwynn is the most famous of their chiefs, and the reason so many young heroes of Stormwind have been carried home.", "A single gnoll is a coward. A pack is a different animal." } },
    { id = "murlocs", title = "Murlocs", section = "peoples", note = { "Murlocs are fish-men of every coast, lake and river of both continents, with wide mouths, many teeth and a gurgling war cry you will hear long before you see them. They live in villages of huts and nets, and they defend them in swarms.", "They are not clever, but they are many, and they come at once. A traveller who fights one murloc on a beach is about to fight six.", "No scholar has yet held a conversation with one. I have tried. The answer was \"Mrglglgl\", and then a spear." } },
    { id = "troggs", title = "Troggs", section = "peoples", note = { "Troggs are hunched, stone-skinned, brutish things that came up out of the deep places when dwarven digging woke them: the Rockjaw of Dun Morogh, the Stonesplinter of Loch Modan, the Stonevault in Uldaman, and others in Gnomeregan and the Badlands.", "The titans' own records in Uldaman say what they are: the makers' first attempt at life from living stone, a failure they buried in vaults. The same records say the dwarves came from stone too, from the earthen who followed. I do not enjoy writing this page.", "They are strong, stupid and never alone. Where you see one trogg, there are a dozen more in the dark." } },
    { id = "ogres", title = "Ogres", section = "peoples", note = { "The ogres came to this world with the Horde, from the orcs' own red land, and when the Horde broke they scattered into the wild in clans of their own: the Mo'grosh of Loch Modan, the Splinter Fist of Duskwood, the Crushridge of Alterac, the Boulderfist of Arathi, the Dustbelcher of the Badlands, the Mosh'Ogg of Stranglethorn, the Gordunni of Feralas and many more.", "Huge, brutal and cleverer than they look, especially the two-headed ogre magi. Their shamans and warlocks are a danger out of proportion to their numbers.", "The Stonemaul of Dustwallow fight beside the Horde. The rest would rather eat you than talk." } },
    { id = "defias", title = "The Defias Brotherhood", section = "peoples", note = { "The Defias Brotherhood began as the Stonemasons' Guild of Stormwind, who rebuilt the city and were never paid for it. Under Edwin VanCleef they became thieves and raiders, and now they hold Westfall and reach into Elwynn and Duskwood, with red masks over their faces.", "They range from thugs and cutpurses on the roads to trained rogues and renegade mages, and their fortress lies under the Deadmines.", "I have met masons who still speak of VanCleef with respect. The farmers of Westfall do not." } },
    { id = "syndicate", title = "The Syndicate", section = "peoples", note = { "The Syndicate are thieves and cutthroats under a lord's banner: the disinherited nobles of Alterac, the kingdom that sold the Alliance to the Horde. They hold the ruined towns of the Alterac Mountains, Durnholde Keep in Hillsbrad, and the ruins of Stromgarde in Arathi.", "They are many, and on the whole not very good at what they do; the assassins of Ravenholdt call them hacks. But a great many thieves can do a great deal of harm.", "Check your purse after walking through the Alterac foothills. Then check it again." } },
    { id = "scarlet-crusade", title = "The Scarlet Crusade", section = "peoples", note = { "The Scarlet Crusade are the survivors of Lordaeron's paladins and priests who swore to burn the undead from the land, and who now burn anyone who looks at them wrongly. They hold Tirisfal's monastery, Hearthglen, Tyr's Hand and half of Stratholme.", "Every stranger might be plagued, every elf or dwarf a spy, and the Forsaken simply the enemy. They are brave, and they have killed more of the Scourge than anyone.", "They will not thank you for the help. They will most likely attack you while you give it." } },
    { id = "cult-of-the-damned", title = "The Cult of the Damned", section = "peoples", note = { "The Cult of the Damned are the living servants of the Lich King: necromancers, acolytes and their students, who spread the plague through Lordaeron's grain and now keep the Scholomance, the Scourge's school of necromancy under Caer Darrow.", "They are men and women who chose the dead, which I find worse than the dead themselves. A ghoul has no choice in what it serves.", "They are found wherever the Scourge is strongest, raising more of it." } },
    { id = "dark-iron-dwarves", title = "Dark Iron Dwarves", section = "peoples", note = { "The Dark Irons are the third of the three hammers, the clan that lost the war for Ironforge and woke the Firelord in its fury. They serve Ragnaros from Blackrock Mountain, and their slaves, diggers and saboteurs reach into the Searing Gorge, the Burning Steppes, the Badlands, Loch Modan and the Wetlands.", "They fight with fire, black powder and a grudge two centuries deep, and they are very good at all three.", "It is a hard thing for an Ironforge dwarf to write this page fairly. I have tried." } },
    { id = "blackrock", title = "The Blackrock Clan", section = "peoples", note = { "The Blackrock were the greatest clan of the old Horde, and those who never went into the camps hold Blackrock Spire and the Burning Steppes still, under Rend Blackhand, who calls himself Warchief. They raid into Redridge and keep the people of Lakeshire penned in their town.", "They are disciplined, well armed and fierce, and they answer, through Rend, to the black dragon who rules the upper Spire.", "Whatever the Horde has become in Durotar, this is what it was." } },
    { id = "dragonmaw", title = "The Dragonmaw Clan", section = "peoples", note = { "The Dragonmaw were the orc clan that rode dragons in the Second War, by holding the red dragon queen captive at Grim Batol. When the dragons were freed, the clan was broken, but its remnants still hold the hills of the Wetlands and raid the roads to Menethil Harbor.", "They are survivors of the old Horde, not followers of the new, and they have not changed their ways.", "Their chieftain dreams of the days when the sky was theirs. The sky has other ideas." } },
    { id = "burning-blade", title = "The Burning Blade", section = "peoples", note = { "The Burning Blade was once an orc clan of blademasters, and is now a cult of warlocks and fanatics who worship the demons that once enslaved their people. They hide in Durotar's caves within sight of Orgrimmar, in the Barrens and in Desolace, and under Orgrimmar itself.", "They answer to the Shadow Council, and they open doors for demons wherever they settle.", "They are the Horde's own shame, hiding in its own lands. Thrall's people hunt them wherever they find them." } },
    { id = "twilights-hammer", title = "The Twilight's Hammer", section = "peoples", note = { "The Twilight's Hammer was an orc clan of the old Horde that believed the world should end, and it has become a cult of every race with the same belief. Its people gather at idols in Blackfathom Deeps, Darkshore, the Searing Gorge and the deserts of Silithus, where they call up elemental lords.", "They worship powers older than the Legion and darker than the dead, and their tracts are mostly about the end of all things.", "They seem to look forward to it. Do not let them hurry it along." } },
    { id = "venture-company", title = "The Venture Company", section = "peoples", note = { "The Venture Company is a goblin concern with no loyalty to anyone but its board: if a thing can be cut down, dug up or pumped out of the ground, they are already there with a shredder. They clear-cut Stonetalon, mine Mulgore's cliffs against the tauren's wishes, foul the Barrens with oil and log the jungle of Stranglethorn.", "Their workers are miners, lumberjacks and engineers more than soldiers, but they defend their claims with goblin enthusiasm and goblin explosives.", "Even other goblins think little of them. That is saying a great deal." } },
    { id = "pirates", title = "Pirates", section = "peoples", note = { "Pirates sail every warm sea of Azeroth. The Bloodsail Buccaneers prey on Booty Bay and the Stranglethorn coast; the Southsea Freebooters hold the Merchant Coast of the Barrens and the coves of Tanaris and rob the goblins' ships.", "They are sailors first and fighters second, but they fight dirty, and in numbers. Their captains are worth a bounty in every goblin port.", "There is no great story behind them, no exiled king or lost cause. They are thieves who own boats, and the sea is wide." } },
    { id = "naga", title = "Naga", section = "peoples", note = { "The naga were the Highborne of Queen Azshara's court, drowned with her palace when the Well of Eternity tore itself apart, and changed in the dark into serpents from the waist down. In the last war they rose from the sea, and now their warbands hold coasts all over the world.", "The Zoram Strand of Ashenvale, the ruins of Azshara and Darkshore, the shores of Feralas, Desolace and the Barrens, and the drowned temple of Blackfathom Deeps: all are theirs. Their sirens and sea witches are as dangerous as any mage.", "They remember when the land was theirs. They would like it back." } },
    { id = "centaurs", title = "Centaurs", section = "peoples", note = { "The centaurs of Kalimdor are the children of Zaetar, a son of Cenarius, and Theradras, a princess of the elemental earth. They were born savage, and in their savagery they killed their own father. Their clans carry the names of the first khans: the Kolkar, the Gelkis and the Magram, the Galak and the Maraudine.", "They are raiders and nothing else: they plant nothing and build little, and take what they want from those who do. For generations they hunted the tauren across the plains.", "A traveller in the Barrens or Desolace learns to listen for hooves." } },
    { id = "quilboar", title = "Quilboar", section = "peoples", note = { "The quilboar are boar-men, spined and tusked, who live among the colossal thorns of the Barrens and call themselves the children of Agamaggan, the boar demigod who fell there in the War of the Ancients. The Razormane, the Bristleback, the Razorfen and the Death's Head are their tribes.", "They fight the centaurs, the tauren and the orcs with equal fury, and they fought them long before the Horde came. In Razorfen Downs, the Death's Head have bargained with the Scourge.", "Their shamans are cleverer than their warriors, and their warriors are very good at being warriors." } },
    { id = "harpies", title = "Harpies", section = "peoples", note = { "Harpies are winged women with taloned feet and arms that end in feathers, as cruel as anything that flies. They nest on the high places of Kalimdor: the Bloodfeather of Teldrassil, the Dustwind of Durotar, the Windfury of Mulgore, the Witchwing of the Barrens, the Bloodfury of Stonetalon and the screeching flocks of Thousand Needles and Feralas.", "Their storm witches call down lightning on caravans and laugh while they do it.", "You will smell their nests before you see them. That, at least, is fair warning." } },
    { id = "furbolgs", title = "Furbolgs", section = "peoples", note = { "Furbolgs are bear-men of the northern forests of Kalimdor, big, slow-spoken and, for most of their long history, peaceful friends of the night elves. Something has gone badly wrong with them. The Gnarlpine of Teldrassil, the Blackwood of Darkshore, the Thistlefur and Foulweald of Ashenvale, the Deadwood of Felwood and the Winterfall of Winterspring have all fallen into madness.", "The night elves blame the corruption that soaks the land, and in Felwood, at least, they are surely right. Only the Timbermaw have kept their minds.", "Fight the mad ones if you must. Mourn them a little afterwards." } },
    { id = "grimtotem", title = "The Grimtotem", section = "peoples", note = { "The Grimtotem are tauren, a tribe that believes the other races have no right to Kalimdor at all, tauren who disagree included. Their matriarch sits among the elders of Thunder Bluff itself; her warriors hold Darkcloud Pinnacle in the Thousand Needles, roam the south of the Barrens, and keep a compound in Feralas.", "They are as strong as any tauren and a good deal less patient.", "Ask a tauren of Freewind Post what he thinks of them, and then step back." } },
    { id = "worgen", title = "Worgen", section = "peoples", note = { "The worgen are wolf-men from somewhere else, tall, grey and terribly strong, who walk upright and run on all fours. In Silverpine the mage Arugal summoned them against the Scourge, lost control of them, and made Shadowfang Keep their den; the people of Pyrewood are men by day and worgen by night.", "The worgen of Duskwood, the Nightbane, are another puzzle: where they came from, nobody in Darkshire can tell me.", "They are cleverer than any wolf. That is all the League knows for certain, and I am in no hurry to learn more." } },
    { id = "forest-trolls", title = "Forest Trolls", section = "peoples", note = { "The forest trolls are the heirs of the Amani empire, which ruled the north before there were men in Lordaeron and fought the elves of Quel'Thalas for generations. Their tribes hold the hills still: the Witherbark of Arathi and the Hinterlands, the Vilebranch in their temple-city of Jintha'Alor, the Mossflayer in the Plaguelands.", "They are tall, green-skinned and tusked, they keep the old gods of the trolls, and some keep worse customs than that.", "The Revantusk of the Hinterlands have taken the Horde's side. The rest have taken nobody's." } },
    { id = "jungle-trolls", title = "Jungle Trolls", section = "peoples", note = { "The jungle trolls of Stranglethorn are the heirs of the Gurubashi empire, whose ruins fill that jungle: the Bloodscalp and the Skullsplitter fight over them, the Atal'ai, whom the empire cast out, serve the blood god in the sunken temple of the Swamp of Sorrows, and in Zul'Gurub the high priests have brought Hakkar back into the world.", "They raid, they take heads, and they hate each other almost as much as they hate everyone else.", "The Darkspear are their cousins, and the only jungle trolls in the world who will share a fire with you." } },
    { id = "sand-trolls", title = "Sand Trolls", section = "peoples", note = { "The Sandfury are the trolls of the Tanaris desert, tall, lean and hard as the sand they live on. Their capital is Zul'Farrak, and they defend what is left of their land against everyone: Alliance, Horde, goblins, ogres, bandits, and above all the insects of the south.", "They worship the great hydra Gahz'rilla in its sacred pool, and they raise their own dead to keep working when they fall.", "The gnomes and goblins of the Shimmering Flats pay well for the scales of their god. I would not ask a Sandfury's opinion of that trade." } },
    { id = "ice-trolls", title = "Ice Trolls", section = "peoples", note = { "The Frostmane are ice trolls, the old masters of Dun Morogh's frozen valleys until dwarven armies drove them into the hills. They hold the caves west of Kharanos still, and when the snow lies deep they come down onto the roads.", "They are not simple beasts. Their seers and shadowcasters keep old and unpleasant rites, and their headhunters earn the name.", "A Frostmane fights like the winter itself: patient, cold, and fond of the weak." } },
    { id = "makrura", title = "Makrura", section = "peoples", note = { "The makrura are crab-folk of the coasts and lakes, armoured and clawed, living in colonies along the shores and shallows of Kalimdor: Durotar and the Barrens, Desolace and Feralas, Dustwallow and Azshara. They are cleverer than crabs and a good deal angrier.", "Their shells are thick and their claws can break a shield. In groups they come scuttling sideways at a speed that seems unfair.", "The orcs of Durotar learn on them, and learn to respect them." } },
    { id = "wildkin", title = "Wildkin", section = "peoples", note = { "The wildkin are great feathered beasts, owl and bear at once, held sacred by the night elves as creatures of Elune. The moonkin of Darkshore are gentle until provoked; the owlbeasts of the Hinterlands and Winterspring are wilder and have not the same patience.", "The night elves say they are not beasts at all, but creatures of the goddess. Having watched one stand guard in the moonlight, I am inclined to agree.", "Approach with respect. Leave with all your feathers, as it were." } },
    { id = "leper-gnomes", title = "Leper Gnomes", section = "peoples", note = { "Not every gnome escaped Gnomeregan. Some lived through the radiation the city was flooded with, and were changed by it: bodies ruined, minds gone strange and violent. They haunt the approaches to the old city and the halls inside it.", "The exiles in Ironforge do not like to talk about them, and I understand why.", "If you must fight them, traveller, remember that they were someone's neighbours once." } },
    { id = "earthen", title = "The Earthen", section = "peoples", note = { "The earthen are beings of living stone, made by the titans to shape the deep places of the world, and in Uldaman some of them still walk the halls of the titans' vault, guarding it as they were made to.", "The platinum discs in that vault say the dwarves descend from them. These are, in the plainest sense, my ancestors, and they will try to kill you.", "I record them with a respect I cannot quite explain, and a caution I can." } },
    { id = "shadow-council", title = "The Shadow Council", section = "peoples", note = { "The Shadow Council are the warlocks who made the old Horde a tool of the Burning Legion, and their cult survives: the Dark Strand of Darkshore and Ashenvale, night elves who have taken up the arts that destroyed their people, and the cultists of Jaedenar in Felwood, who keep demons close and make their pacts with the Legion.", "The Burning Blade answers to them. So, in the end, do the demons they summon, until the demons decide otherwise.", "Where you find their circles, look for the doorway they are trying to open." } },
    { id = "servants-of-the-firelord", title = "Servants of the Firelord", section = "peoples", note = { "In the Molten Core, under Blackrock Mountain, Ragnaros keeps servants of his own making: the Flamewakers, tall and burning, and the creatures of fire that guard his domain. They are not elementals as the wild ones are, nor mortals; they are the Firelord's household.", "They are encountered only in the deepest fires of the mountain, and they defend their master with everything they are.", "Few travellers record them. Fewer come back to finish the entry." } },
    { id = "lost-ones", title = "The Lost Ones", section = "peoples", note = { "In the east of the Swamp of Sorrows live the Lost Ones: tall, blue-grey, hooved and tendrilled, people who look like nothing else in Azeroth. A few exiles of their kind, at the Harborage, are sane and gentle and call themselves draenei; they came to this world from the orcs' own, they say.", "The journey broke the others. They live like beasts in the Fallow Sanctuary and kill any who come near.", "What they were before, the exiles do not like to say, and I have not pressed them." } },
    { id = "goblins", title = "Goblins", section = "peoples", note = { "Most goblins a traveller meets are selling something, and most of the rest are working for someone who is. This page holds the ones who are trying to kill you instead: the engineers and craftsmen of the Deadmines who build VanCleef's ship, the tinkerers who have set up shop in dangerous places, and the odd mad genius with a grudge.", "They fight with whatever they have built, which is usually explosive, and whatever they have hired, which is usually large.", "The Venture Company has a page of its own. These are the freelancers." } },
    { id = "hostile-elves", title = "Hostile Elves", section = "peoples", note = { "Not every elf in Azeroth is a friend of the Alliance. In Azshara, blood elves of Quel'Thalas have come looking for the Highborne's lost magic among the ruins, and they defend their finds with spells. In Dire Maul, Lethtendris and others feed on the arcane power still trapped in the city.", "They are few, clever and very dangerous to anyone carrying a spellbook.", "The night elves of Darnassus regard them with a suspicion ten thousand years old. Having met them, I find the suspicion well founded." } },
    { id = "druids-of-the-fang", title = "The Druids of the Fang", section = "peoples", note = { "The Druids of the Fang were disciples of the night elf druid Naralex, who went down into the Wailing Caverns to heal the Barrens through the Emerald Dream. The dream went wrong. Naralex has not woken, and his disciples have been twisted by the nightmare that took him.", "They have taken the shapes and names of serpents, Lord Cobrahn, Lady Anacondra, Lord Pythas and Lord Serpentis among them, and they mean to remake the land after their own dreams.", "The druids of Thunder Bluff say their faces haunt them. I would not seek them out without a good reason and good company." } },
    { id = "bandits-and-mercenaries", title = "Bandits and Mercenaries", section = "peoples", note = { "Not every human foe flies a banner. Bandits haunt the desert roads of Tanaris, deserters and renegades lurk in the hills, and in Stranglethorn the men of Colonel Kurzen, once soldiers of the Alliance, have become something crueller, hunting and raiding from their camp in the north of the jungle.", "They are men and women gone wrong, for gold or power or reasons nobody has asked them.", "They are the most dangerous creatures in this book in one respect: they think the way you do." } },
    { id = "other-peoples", title = "Other Humanoids", section = "peoples", note = { "This page holds the people no other page claims: lone outlaws and named villains, the servants of a single dungeon, captives and mad hermits, and the foes of every race who fight for no banner the League can name.", "Many of them are the subject of a wanted poster in some village or other, and the bounty is often the best part of their story.", "If you meet one worth a page of their own, write to the League. We are always short of good stories." } },
    { id = "silithid", title = "Silithid and Qiraji", section = "oddities", note = { "The silithid are the insects of the south, and no insect you have ever swatted: wasps the size of hounds, tunnelers that bring down caves, reavers as big as an ogre. They hollow out the deserts of Silithus, Tanaris and Un'Goro, and their hives push north into Feralas and the Barrens.", "Their masters are the Qiraji, an older and cleverer kind, who rule from Ahn'Qiraj behind the Scarab Wall. A thousand years ago they sent their swarms against the night elves, and were sealed away by the elves and the dragons together.", "The hives are spreading again. Each year the scouts of Kalimdor find new mounds, a little further north." } },
    { id = "oddities", title = "Strange Creatures", section = "oddities", note = { "Some creatures belong to no family this naturalist can name: the beasts of a single lake, monsters of a single dungeon, things grown strange in the Wailing Caverns or Maraudon, and the great powers that a whole tribe worships.", "Many are the only one of their kind. Some are worshipped, some feared, a few merely inexplicable.", "Record what you can. Where I have no family to give them, I can at least give them a page." } },
