  atlas = {
    continents = { [1414] = "Kalimdor", [1415] = "Eastern Kingdoms" },
    zones = {
      [1411] = { name = "Durotar", continent = 1414, note = { "Red rock and dry gullies, the land Thrall gave his people. Orgrimmar stands in the north; the road runs south from its gate to Razor Hill and on to Sen'jin Village on the coast, and west over the river into the Barrens.", "New orcs and trolls are trained in the Valley of Trials. The Darkspear keep Sen'jin, though the Echo Isles offshore are not theirs at present. The Burning Blade hides in the caves of Skull Rock, the Kolkar centaurs hold their crag, and the Kul Tirans still keep Tiragarde Keep on the eastern coast.", "The zeppelins leave from towers outside Orgrimmar. Do not stand underneath one." }, places = { { "Drygulch Ravine", 475, 120, 575, 210, 370 }, { "Echo Isles", 600, 470, 710, 660, 368 }, { "Kolkar Crag", 460, 500, 520, 560, 366 }, { "Orgrimmar", 355, 10, 585, 60, 1637 }, { "Razor Hill", 500, 245, 595, 325, 362 }, { "Razormane Grounds", 350, 230, 475, 350, 816 }, { "Sen'jin Village", 525, 450, 600, 525, 367 }, { "Skull Rock", 500, 55, 575, 105, 817 }, { "Thunder Ridge", 355, 105, 460, 220, 369 }, { "Tiragarde Keep", 535, 325, 620, 425, 372 }, { "Valley of Trials", 395, 395, 495, 500, 363 } } },
      [1412] = { name = "Mulgore", continent = 1414, note = { "Green plains and grazing kodo under a big sky: the tauren's home. Thunder Bluff stands on its mesas in the north; Bloodhoof Village sits in the south, and the road runs between them and out east to the Barrens.", "The plains are kind, mostly. The water wells are the tauren's, and worth guarding; the gnolls of Palemane Rock, the harpies of Windfury Ridge and the Venture Company's mine are not. The dwarves at the Bael'dun digsite dig where the tauren would rather they did not.", "Red Rocks, in the east, is a resting place of the tauren's honoured dead. Walk there quietly." }, places = { { "Bael'dun Digsite", 280, 309, 373, 369, 404 }, { "Bloodhoof Village", 434, 388, 507, 445, 222 }, { "Brambleblade Ravine", 546, 495, 684, 584, 358 }, { "Palemane Rock", 311, 424, 373, 491, 818 }, { "Ravaged Caravan", 497, 331, 546, 372, 224 }, { "Red Cloud Mesa", 386, 510, 549, 597, 220 }, { "Red Rocks", 536, 168, 622, 254, 225 }, { "Skywatcher Plateau", 218, 0, 521, 225, 17045 }, { "The Golden Plains", 457, 203, 534, 329, 820 }, { "The Rolling Plains", 549, 422, 662, 488, 821 }, { "The Venture Co. Mine", 559, 315, 628, 381, 360 }, { "Thunder Bluff", 323, 195, 467, 289, 1638 }, { "Thunderhorn Water Well", 417, 312, 473, 356, 397 }, { "Wildmane Water Well", 399, 138, 454, 187, 398 }, { "Windfury Ridge", 454, 101, 561, 173, 819 }, { "Winterhoof Water Well", 501, 437, 539, 483, 396 } } },
      [1413] = { name = "The Barrens", continent = 1414, note = { "A great dry plain with one crossroads in the middle of it, and the Crossroads knows it. Every road meets there: north to Ashenvale past the Mor'shan Rampart, east to Ratchet and the sea, south through Camp Taurajo to the Great Lift and the Thousand Needles, west into the hills of Stonetalon.", "Water is the whole question. The oases are few and fouled, the wells are guarded, and the grass hides more than it shows: quilboar in the thorn-mounds, centaurs on the horizon, and in the south the bramble-walls of Razorfen, which you will want to see once and never again.", "Ratchet's boat goes to Booty Bay, and the goblins will take anyone's money. Fill your waterskin before you leave the Crossroads, whatever the innkeeper charges." }, places = { { "Agama'gor", 390, 275, 475, 370, 1700 }, { "Bael Modan", 450, 530, 505, 590, 359 }, { "Blackthorn Ridge", 385, 490, 450, 565, 1701 }, { "Boulder Lode Mine", 595, 10, 645, 80, 381 }, { "Bramblescar", 485, 355, 530, 425, 1698 }, { "Camp Taurajo", 425, 380, 490, 435, 378 }, { "Dreadmist Peak", 450, 95, 520, 150, 384 }, { "Far Watch Post", 590, 115, 635, 170, 379 }, { "Field of Giants", 425, 445, 500, 500, 390 }, { "Grol'dom Farm", 530, 105, 585, 150, 1704 }, { "Honor's Stand", 335, 155, 415, 225, 1702 }, { "Lushwater Oasis", 435, 225, 500, 295, 387 }, { "Northwatch Hold", 575, 340, 650, 400, 385 }, { "Raptor Grounds", 530, 320, 590, 365, 1697 }, { "Ratchet", 600, 225, 655, 275, 392 }, { "Razorfen Downs", 445, 580, 535, 645, 1316 }, { "Razorfen Kraul", 370, 555, 450, 625, 1717 }, { "The Crossroads", 485, 165, 550, 215, 380 }, { "The Dry Hills", 350, 60, 445, 135, 383 }, { "The Forgotten Pools", 420, 125, 490, 190, 386 }, { "The Merchant Coast", 615, 270, 660, 335, 391 }, { "The Mor'shan Rampart", 440, 15, 520, 75, 1703 }, { "The Sludge Fen", 505, 20, 605, 80, 382 }, { "The Stagnant Oasis", 530, 255, 585, 315, 388 }, { "Thorn Hill", 540, 165, 600, 215, 1699 } } },
      [1416] = { name = "Alterac Mountains", continent = 1415, note = { "High, cold and treacherous, in every sense. Alterac was a kingdom, and it sold the Alliance to the Horde; what is left of it is ruins, the ruined capital among them, held by the Syndicate and the ogres of Crushridge Hold.", "On the shore of Lordamere Lake the mages of Dalaran rebuild their city behind a violet dome that admits nobody. Near it lies the old internment camp where orcs were once held. Strahnbrad, on the road from Hillsbrad, is a Syndicate town now; walk through it, not into it.", "The snow hides the paths, and the paths hide yetis. Hire a guide in Hillsbrad if you value your toes." }, places = { { "Chillwind Point", 730, 330, 915, 560, 1684, 3486 }, { "Corrahn's Dagger", 435, 495, 530, 625, 1679 }, { "Crushridge Hold", 435, 215, 535, 345, 282, 283 }, { "Dalaran", 75, 360, 230, 520, 279 }, { "Dandred's Fold", 370, 70, 440, 160, 1682 }, { "Gallows' Corner", 460, 355, 545, 430, 1357 }, { "Gavin's Naze", 270, 525, 345, 620, 1677 }, { "Growless Cave", 345, 420, 450, 505, 1683 }, { "Lordamere Internment Camp", 160, 525, 250, 610, 278 }, { "Misty Shore", 220, 190, 345, 315, 1681 }, { "Ruins of Alterac", 330, 295, 470, 420, 281 }, { "Sofera's Naze", 540, 415, 630, 505, 1678 }, { "Strahnbrad", 570, 255, 700, 350, 280 }, { "The Headland", 345, 545, 435, 660, 1680 }, { "The Uplands", 500, 120, 630, 245, 284 } } },
      [1417] = { name = "Arathi Highlands", continent = 1415, note = { "Green hills and old stones: this is the cradle of the human kingdoms, and its ruins are older than Stormwind. The road crosses Thandol Span from the Wetlands and runs north to Thoradin's Wall and Hillsbrad beyond it.", "Refuge Pointe holds for the Alliance, Hammerfall for the Horde, and Stromgarde Keep for nobody in particular any more: the Syndicate, the ogres and the Witherbark trolls all have a share of it. The standing stones of the binding circles are worth a look and not worth a long stay.", "Faldir's Cove on the south coast has a wreck in it and pirates on the wreck. Approach from the cliffs." }, places = { { "Boulder'gor", 350, 215, 405, 340, 1858 }, { "Boulderfist Hall", 475, 425, 610, 560, 316 }, { "Circle of East Binding", 595, 175, 680, 280, 333 }, { "Circle of Inner Binding", 315, 365, 420, 460, 335 }, { "Circle of Outer Binding", 485, 320, 570, 385, 336 }, { "Circle of West Binding", 170, 110, 275, 230, 334 }, { "Dabyrie's Farmstead", 505, 230, 600, 300, 315 }, { "Faldir's Cove", 215, 475, 405, 590, 327 }, { "Go'Shek Farm", 575, 340, 655, 415, 314 }, { "Hammerfall", 690, 190, 815, 300, 321 }, { "Northfold Manor", 275, 150, 360, 270, 313 }, { "Refuge Pointe", 420, 260, 500, 370, 320 }, { "Stromgarde Keep", 140, 340, 315, 490, 324 }, { "Thandol Span", 400, 485, 520, 625, 880 }, { "Thoradin's Wall", 125, 180, 230, 325, 1857 }, { "Witherbark Village", 595, 410, 740, 485, 317 } } },
      [1418] = { name = "Badlands", continent = 1415, note = { "Red rock, no water and a sun that hates you. The road comes down from Loch Modan and crosses the waste west to Kargath, the Horde's outpost.", "Somewhere in these canyons the titans built Uldaman, and the League has spent years digging it out; the dig at Hammertoe's camp is the place to ask. The Dark Irons hold Angor Fortress, the ogres hold their camps in the south, and the black dragons nest in Lethlor Ravine.", "Carry twice the water you think you need, and travel at dawn. The coyotes will follow you anyway." }, places = { { "Agmond's End", 400, 420, 545, 570, 345 }, { "Angor Fortress", 360, 170, 500, 275, 338 }, { "Apocryphan's Rest", 100, 360, 215, 465, 337 }, { "Camp Boff", 545, 400, 685, 570, 342 }, { "Camp Cagg", 40, 475, 225, 615, 344 }, { "Camp Kosh", 600, 100, 725, 200, 341 }, { "Dustwind Gulch", 565, 245, 690, 370, 1898 }, { "Hammertoe's Digsite", 500, 190, 635, 295, 346 }, { "Kargath", 10, 265, 165, 370, 340 }, { "Lethlor Ravine", 685, 225, 885, 455, 339 }, { "Mirage Flats", 215, 420, 400, 585, 1879 }, { "The Dustbowl", 220, 275, 390, 415, 1878 }, { "The Maker's Terrace", 400, 50, 585, 170, 1897 }, { "Valley of Fangs", 400, 320, 530, 440, 1877 } } },
      [1419] = { name = "Blasted Lands", continent = 1415, note = { "A red, dead waste around the Dark Portal, where the orcs first came into the world. The Portal is dark now. Nethergarde Keep, on the northern rise, still watches it with mages and soldiers who would rather be anywhere else.", "The ogres of Dreadmaul hold the hills, demons walk the Tainted Scar, and the beasts that live here are the ones nothing else would eat. The road comes south from the Swamp of Sorrows and ends at Nethergarde; beyond it, there is no road.", "There is no water fit to drink and no game fit to eat. Bring both." }, places = { { "Altar of Storms", 365, 180, 430, 245, 1441 }, { "Dreadmaul Hold", 385, 65, 480, 125, 1437 }, { "Dreadmaul Post", 450, 255, 560, 335, 1439 }, { "Garrison Armory", 520, 65, 600, 120, 1457 }, { "Nethergarde Keep", 595, 85, 695, 160, 1438 }, { "Rise of the Defiler", 445, 160, 530, 240, 2517 }, { "Serpent's Coil", 575, 190, 685, 255, 1440 }, { "The Dark Portal", 520, 325, 650, 430, 72 }, { "The Tainted Scar", 265, 295, 495, 540, 73 } } },
      [1420] = { name = "Tirisfal Glades", continent = 1415, note = { "The heart of old Lordaeron, gone grey and quiet. Under the ruins of its capital lies the Undercity of the Forsaken, and from Deathknell, where the Forsaken wake, the road runs east through Brill to the ruins and on to the Bulwark at the edge of the Plaguelands.", "The farms are haunted, the lake is full of murlocs, and the Scarlet Crusade holds the north-east, with its monastery and its watch posts, burning anything that looks dead. In Tirisfal, that is most things.", "Brill's inn is the best fire for a hundred miles. The zeppelins to Orgrimmar and Grom'gol leave from a tower near the ruins." }, places = { { "Agamand Mills", 384, 183, 522, 303, 157 }, { "Balnir Farmstead", 664, 335, 795, 489, 165 }, { "Brightwater Lake", 633, 165, 735, 398, 162 }, { "Brill", 560, 320, 635, 418, 159 }, { "Cold Hearth Manor", 502, 365, 575, 436, 166 }, { "Crusader Outpost", 708, 292, 853, 395, 167 }, { "Deathknell", 279, 366, 411, 488, 154 }, { "Garren's Haunt", 531, 182, 627, 328, 164 }, { "Nightmare Vale", 401, 396, 547, 490, 811 }, { "Ruins of Lordaeron", 463, 361, 783, 617, 153 }, { "Scarlet Watch Post", 740, 114, 820, 325, 459 }, { "Solliden Farmstead", 284, 290, 437, 371, 156 }, { "Stillwater Pond", 429, 307, 532, 378, 810 }, { "Terrace of Repose", 746, 125, 1002, 381, 161, 160 }, { "The Bulwark", 770, 380, 905, 550, 152 }, { "Venomweb Vale", 777, 240, 970, 408, 812 }, { "Whispering Forest", 4, 198, 339, 622, 16616 } } },
      [1421] = { name = "Silverpine Forest", continent = 1415, note = { "Grey pines on a grey coast, between the Forsaken's Tirisfal and the wall of Gilneas. The Sepulcher is the Forsaken's town, in the middle of the forest; the road runs north to Tirisfal and south past Pyrewood to Hillsbrad.", "Pyrewood Village looks like any village by day. Do not be in it at night. On the hill above it stands Shadowfang Keep, where the archmage Arugal keeps his worgen, and in the south the Greymane Wall shuts Gilneas away from the world, and has done so for years.", "Ambermill, on the eastern hills, belongs to mages of Dalaran who do not want visitors. Believe them." }, places = { { "Ambermill", 580, 370, 690, 470, 233 }, { "Beren's Peril", 550, 450, 630, 515, 231 }, { "Deep Elem Mine", 530, 285, 595, 360, 213 }, { "Fenris Isle", 625, 125, 815, 260, 172 }, { "Malden's Orchard", 535, 50, 600, 90, 238 }, { "North Tide's Hollow", 365, 160, 445, 220, 928 }, { "Olsen's Farthing", 430, 330, 510, 390, 229 }, { "Pyrewood Village", 410, 465, 490, 520, 204 }, { "Shadowfang Keep", 390, 410, 495, 475, 236 }, { "The Dead Field", 430, 115, 500, 175, 240 }, { "The Decrepit Ferry", 510, 205, 600, 280, 237 }, { "The Greymane Wall", 420, 530, 510, 620, 230 }, { "The Sepulcher", 405, 240, 490, 305, 228 }, { "The Shining Strand", 510, 115, 575, 190, 927 }, { "The Skittering Dark", 325, 70, 425, 140, 226 } } },
      [1422] = { name = "Western Plaguelands", continent = 1415, note = { "This is where the plague took hold. The fields are rotten, the farms are haunted, and the town of Andorhal, where the plague grain was stored, is a ruin full of the dead. The road enters from Tirisfal at the Bulwark and runs east to the Thondroril River and the worse country beyond it.", "The Scarlet Crusade holds Hearthglen in the north. In the south, on an island in Darrowmere Lake, Caer Darrow hides the Scholomance, the Scourge's school of necromancy. The Alliance keeps Chillwind Camp nearby, for those who go there on purpose.", "Boil your water. Then boil it again, and drink something else." }, places = { { "Caer Darrow", 640, 455, 740, 550, 2298 }, { "Dalson's Tears", 420, 315, 510, 390, 200 }, { "Darrowmere Lake", 555, 410, 815, 575, 2297 }, { "Felstone Field", 335, 340, 415, 405, 199 }, { "Gahrron's Withering", 580, 345, 680, 420, 201 }, { "Hearthglen", 365, 55, 580, 185, 190 }, { "Northridge Lumber Camp", 425, 195, 525, 290, 192 }, { "Ruins of Andorhal", 380, 420, 495, 505, 193 }, { "Sorrow Hill", 470, 485, 565, 575, 197 }, { "The Bulwark", 205, 350, 325, 425, 813 }, { "The Weeping Cave", 615, 240, 690, 325, 198 }, { "The Writhing Haunt", 500, 405, 570, 470, 202 }, { "Thondroril River", 625, 120, 730, 395, 2620 } } },
      [1423] = { name = "Eastern Plaguelands", continent = 1415, note = { "The worst country in the world, and I have walked the Blasted Lands. The Thondroril River marks its edge; beyond it the trees are dead, the earth is sick and the plague's own city, Stratholme, stands in the north-west, burned and still full.", "Light's Hope Chapel in the east is the Argent Dawn's, and the only safe roof here. The Scarlet Crusade holds Tyr's Hand in the south-east; the Mossflayer trolls hold Zul'Mashar; and above the Plaguewood, these days, a dark citadel hangs in the sky.", "Darrowshire is a ghost town in the plainest sense. Some of the ghosts will talk to you. Listen to them." }, places = { { "Blackwood Lake", 475, 290, 565, 375, 2624 }, { "Corin's Crossing", 550, 430, 645, 510, 2264 }, { "Crown Guard Tower", 345, 465, 430, 545, 2263 }, { "Darrowshire", 340, 560, 460, 640, 2262 }, { "Eastwall Tower", 645, 290, 715, 375, 2271 }, { "Lake Mereldar", 565, 490, 690, 580, 2621 }, { "Light's Hope Chapel", 785, 350, 860, 430, 2268 }, { "New Avalon", 678, 202, 1002, 668, 16335 }, { "Northdale", 665, 170, 750, 255, 2272 }, { "Northpass Tower", 515, 145, 645, 235, 2275 }, { "Pestilent Scar", 695, 355, 790, 480, 2622 }, { "Plaguewood", 235, 160, 495, 290, 2277 }, { "Quel'Lithien Lodge", 485, 80, 575, 140, 2276 }, { "Stratholme", 245, 35, 380, 170, 2279 }, { "Terrordale", 115, 180, 240, 250, 2627 }, { "The Fungal Vale", 355, 300, 455, 395, 2258 }, { "The Infectis Scar", 475, 405, 580, 485, 2623 }, { "The Marris Stead", 215, 455, 320, 525, 2260 }, { "The Noxious Glade", 785, 225, 905, 330, 2270 }, { "The Undercroft", 245, 520, 325, 610, 2261 }, { "Thondroril River", 25, 255, 130, 550, 2619 }, { "Tyr's Hand", 765, 505, 935, 605, 2266 }, { "Zul'Mashar", 670, 60, 795, 135, 2273 } } },
      [1424] = { name = "Hillsbrad Foothills", continent = 1415, note = { "Farm country on the foothills of Alterac, and fought over farm by farm. Southshore holds the coast for the Alliance; Tarren Mill holds the hills for the Forsaken; between them, the fields of Hillsbrad change hands with the season.", "Durnholde Keep, on its hill above the road, was once the prison camp where the orcs were held after the Second War. The Syndicate have it now. The road runs north from Arathi through the wall, and on into Alterac and Silverpine, and a branch climbs east to the Hinterlands.", "The Southshore inn is good and loud. Keep your voice down about Tarren Mill in it." }, places = { { "Azurelode Mine", 215, 345, 310, 420, 288 }, { "Darrow Hill", 435, 190, 585, 260, 1056 }, { "Dun Garok", 675, 405, 770, 550, 290 }, { "Durnholde Keep", 705, 220, 835, 325, 275 }, { "Eastern Strand", 550, 440, 690, 555, 294 }, { "Hillsbrad Fields", 250, 200, 450, 400, 286 }, { "Nethander Stead", 580, 290, 700, 450, 289 }, { "Purgation Isle", 110, 480, 235, 585, 896 }, { "Southpoint Tower", 75, 245, 235, 370, 285 }, { "Southshore", 445, 310, 550, 430, 271 }, { "Tarren Mill", 545, 100, 680, 245, 272 }, { "Western Strand", 240, 415, 475, 495, 295 } } },
      [1425] = { name = "The Hinterlands", continent = 1415, note = { "Wild green hills, and the Wildhammer's. Aerie Peak, in the west, is their home and their gryphons', and the only friendly hearth for an Alliance traveller. The road climbs in from Hillsbrad and winds east past old troll ruins.", "The Witherbark hold old troll ruins across the hills; the Vilebranch hold Jintha'Alor, their temple-city in the south-east, and the spider-goddess Shadra has her own temple. In the north, around a great tree at Seradane, the green dragons sleep badly.", "Wildhammer dwarves are not Ironforge dwarves. Do not say so to their faces, and do not ask for directions to the brewery: they will assume you are thirsty." }, places = { { "Aerie Peak", 85, 285, 210, 390, 348 }, { "Agol'watha", 440, 205, 555, 290, 1884 }, { "Hiri'watha", 230, 365, 335, 460, 1885 }, { "Jintha'Alor", 550, 360, 700, 570, 354 }, { "Plaguemist Ravine", 190, 180, 265, 330, 1882 }, { "Quel'Danil Lodge", 255, 225, 375, 350, 350 }, { "Seradane", 560, 90, 725, 250, 356 }, { "Shadra'Alor", 295, 430, 400, 525, 353 }, { "Shaol'watha", 635, 285, 770, 390, 1917 }, { "Skulk Rock", 550, 250, 635, 325, 351 }, { "The Altar of Zul", 440, 405, 535, 480, 355 }, { "The Creeping Ruin", 455, 315, 550, 400, 1886 }, { "The Overlook Cliffs", 755, 350, 835, 570, 307 }, { "Valorwind Lake", 365, 355, 440, 425, 1883 } } },
      [1426] = { name = "Dun Morogh", continent = 1415, note = { "Snow, stone and dwarves, in that order. The valleys run east and west below the peaks that hide Ironforge, and the one road follows them: from Coldridge Valley through the tunnel to Kharanos, up to the city's great gate, and on east through the pass to Loch Modan.", "Kharanos has the Thunderbrew distillery and the best fire in the land. West of it the ground belongs to the Frostmane trolls, and further west Gnomeregan stands behind its walls, poisoned; the gnomes do not go home, and you should not go in without good reason and better friends.", "Carry a spare cloak and keep to the road in a snowstorm. The drifts are deep, and the troggs of Coldridge do not care that you are lost." }, places = { { "Amberstill Ranch", 605, 315, 665, 360, 803 }, { "Brewnall Village", 280, 275, 330, 340, 137 }, { "Chill Breeze Valley", 320, 320, 400, 390, 801 }, { "Coldridge Pass", 320, 420, 380, 490, 800 }, { "Coldridge Valley", 190, 445, 340, 560, 132, 77 }, { "Frostmane Hold", 260, 315, 305, 375, 135 }, { "Gnomeregan", 205, 215, 280, 295, 133 }, { "Gol'Bolar Quarry", 640, 340, 735, 430, 134 }, { "Helm's Bed Lake", 730, 315, 810, 410, 212 }, { "Iceflow Lake", 315, 195, 385, 320, 211 }, { "Ironforge", 397, 163, 717, 419, 1537, 809 }, { "Kharanos", 386, 294, 642, 550, 131 }, { "Misty Pine Refuge", 545, 245, 605, 325, 138 }, { "North Gate Outpost", 800, 205, 860, 300, 808 }, { "Shimmer Ridge", 380, 220, 440, 315, 802 }, { "South Gate Outpost", 825, 305, 885, 375, 806 }, { "The Grizzled Den", 380, 350, 440, 425, 136 }, { "The Tundrid Hills", 555, 355, 645, 410, 804 } } },
      [1427] = { name = "Searing Gorge", continent = 1415, note = { "A burned country of slag and cinders, worked by Dark Iron slaves around the Cauldron, a great pit at its heart. The Thorium Brotherhood, dwarves who left the Dark Irons, keep a camp here and will trade with anyone who proves useful.", "Most travellers come in through Blackrock Mountain, where the gorge meets the Burning Steppes. The rest of the gorge is mines, digs, fire elementals, lava spiders and the Dark Irons' overseers.", "The ground is hot underfoot. Mind your boots; the soles will not last." }, places = { { "Blackchar Cave", 155, 415, 305, 565, 1957 }, { "Dustfire Valley", 530, 60, 820, 330, 1959 }, { "Firewatch Ridge", 160, 130, 400, 320, 1442 }, { "Grimesilt Dig Site", 560, 345, 740, 440, 247 }, { "Tanner Camp", 605, 440, 785, 580, 1958 }, { "The Cauldron", 315, 260, 610, 400, 246 }, { "The Sea of Cinders", 330, 460, 570, 665, 1444 } } },
      [1428] = { name = "Burning Steppes", continent = 1415, note = { "Ash and fire, the country south of Blackrock Mountain. The mountain itself stands on the northern edge, the Firelord in its heart and the black dragons at its top; the Blackrock orcs hold its stronghold, and their worgs and ogres hold the plain.", "The road comes up from Redridge through Render's Valley. Morgan's Vigil, on the eastern cliffs, is the Alliance's foothold; it is a small one. The black dragonflight nests at Draco'dar, and its whelps are everywhere.", "There is nothing to eat here that will not try to eat you first. Bring supplies." }, places = { { "Altar of Storms", 100, 150, 215, 280, 255 }, { "Blackrock Mountain", 220, 145, 380, 280, 254 }, { "Blackrock Pass", 680, 385, 825, 530, 2417 }, { "Blackrock Stronghold", 370, 160, 505, 310, 252 }, { "Draco'dar", 125, 330, 435, 545, 2421 }, { "Dreadmaul Rock", 745, 205, 885, 350, 249 }, { "Morgan's Vigil", 805, 350, 970, 515, 2418 }, { "Ruins of Thaurissan", 550, 145, 755, 315, 250 }, { "Terror Wing Path", 780, 115, 995, 365, 2420 }, { "The Pillar of Ash", 415, 325, 590, 430, 253 } } },
      [1429] = { name = "Elwynn Forest", continent = 1415, note = { "The gentlest country in the Eastern Kingdoms, and the best mapped: the King's road runs from the gates of Stormwind through Goldshire and on east to Redridge, and every farm along it has been surveyed, taxed and argued over. Northshire Abbey sits in its own valley to the north, where Stormwind trains its young.", "Water is never far: Crystal Lake, Stone Cairn Lake, Mirror Lake and the river that marks the Westfall border. The danger is underground. The kobolds have the Jasperlode and Fargodeep mines, and the Defias have more of the forest's farms than the Crown likes to admit.", "Keep off the road south-west of Goldshire after dark. Something large lives in the woods there, and the guards have stopped going to look." }, places = { { "Brackwell Pumpkin Patch", 615, 495, 735, 565, 62 }, { "Crystal Lake", 450, 380, 605, 475, 18 }, { "Eastvale Logging Camp", 775, 400, 900, 485, 88 }, { "Fargodeep Mine", 300, 510, 470, 615, 57 }, { "Forest's Edge", 200, 445, 300, 645, 60 }, { "Goldshire", 370, 400, 455, 465, 87 }, { "Jerod's Landing", 460, 495, 615, 615, 797 }, { "Northshire Valley", 425, 190, 600, 375, 9 }, { "Ridgepoint Tower", 790, 505, 915, 570, 798 }, { "Stone Cairn Lake", 675, 250, 830, 415, 86 }, { "Stormwind City", 115, 120, 370, 355, 1519, 1617, 80 }, { "Tower of Azora", 610, 400, 745, 490, 91 } } },
      [1430] = { name = "Deadwind Pass", continent = 1415, note = { "A dead valley between Duskwood and the Swamp of Sorrows, and the road between them runs through it as fast as it can. Nothing grows here, and the ravens are the only thing that seems at home.", "In the south stands Karazhan, the tower of Medivh, the last Guardian. It is sealed, it is haunted, and the League has not yet found anyone willing to survey it.", "Do not camp in the pass. Nobody who knows it would." }, places = { { "Deadman's Crossing", 315, 125, 590, 355, 2697 }, { "Karazhan", 335, 380, 520, 540, 2562 }, { "The Vice", 510, 325, 665, 540, 2561 } } },
      [1431] = { name = "Duskwood", continent = 1415, note = { "A forest where the sun never quite gets through, and the only town is Darkshire, held by the Night Watch with more courage than men. The road runs from Elwynn in the north down through the woods to Stranglethorn, with a branch west towards Westfall and another east to Deadwind Pass.", "Everything off the road is somebody's grave. The dead walk out of Raven Hill's cemetery, wolves and spiders own the woods, and the farms of the Rotting Orchard and Brightwood Grove have worse than wolves in them. Manor Mistmantle has stood empty for years; there is a reason for that.", "Travel by day, stay on the road, and listen to the town historian before you go anywhere he warns you about." }, places = { { "Addle's Stead", 160, 415, 275, 510, 536 }, { "Brightwood Grove", 570, 165, 685, 380, 242 }, { "Darkshire", 710, 250, 835, 350, 42 }, { "Manor Mistmantle", 695, 195, 795, 255, 1098 }, { "Raven Hill", 155, 340, 260, 410, 94 }, { "Raven Hill Cemetery", 145, 210, 260, 350, 492 }, { "The Darkened Bank", 125, 85, 970, 200, 799 }, { "The Hushed Bank", 56, 191, 145, 403, 1097 }, { "The Rotting Orchard", 580, 430, 705, 545, 241 }, { "The Yorgen Farmstead", 445, 440, 540, 540, 245 }, { "Tranquil Gardens Cemetery", 755, 430, 850, 505, 121 }, { "Twilight Grove", 370, 145, 585, 395, 856 }, { "Vul'Gol Ogre Mound", 285, 435, 440, 545, 93 } } },
      [1432] = { name = "Loch Modan", continent = 1415, note = { "A long lake held back by the Stonewrought Dam, the finest piece of dwarven engineering outside Ironforge, and I will hear no argument. Thelsamar sits on the western shore on the road from Dun Morogh, and the road goes on north to the Wetlands and south to the Badlands.", "The Valley of Kings at the pass has stone kings to watch over it. The rest of the country needs watching: troggs in Stonesplinter Valley, kobolds in the mines, and ogres in the Mo'grosh Stronghold in the north-east hills.", "The high elves of the Farstrider Lodge keep to themselves and know the country better than any dwarf. Ask them before you go hunting." }, places = { { "Grizzlepaw Ridge", 395, 395, 510, 525, 936 }, { "Ironband's Excavation Site", 625, 380, 765, 495, 142 }, { "Mo'grosh Stronghold", 620, 105, 800, 230, 143 }, { "North Gate Pass", 160, 45, 290, 160, 838 }, { "Silver Stream Mine", 290, 90, 400, 200, 149 }, { "Stonesplinter Valley", 275, 430, 425, 610, 923 }, { "Stonewrought Dam", 380, 45, 580, 125, 146 }, { "The Farstrider Lodge", 790, 380, 875, 460, 147 }, { "The Loch", 405, 115, 600, 450, 556 }, { "Thelsamar", 300, 265, 400, 350, 144 }, { "Valley of Kings", 150, 400, 260, 585, 924 } } },
      [1433] = { name = "Redridge Mountains", continent = 1415, note = { "Red hills around a long blue lake, and the town of Lakeshire on its western shore, joined by a bridge that the whole valley depends on. The road comes in from Elwynn to the west and meets the road to Duskwood at Three Corners.", "Lake Everstill is beautiful and full of murlocs. The hills are worse: gnolls on the ridges, and in the east the Blackrock orcs hold Stonewatch and the valley beyond it, and come down at night to see what they can burn.", "If Lakeshire asks you for help, give it. There is nobody else between the Blackrock and Stormwind, and the people of the town know it." }, places = { { "Alther's Mill", 410, 233, 549, 337, 97 }, { "Galardell Valley", 626, 208, 798, 353, 1000, 96 }, { "Lake Everstill", 302, 338, 540, 461, 68 }, { "Lakeridge Highway", 219, 459, 528, 569, 1001 }, { "Lakeshire", 94, 263, 334, 342, 69 }, { "Redridge Canyons", 117, 131, 351, 252, 95, 98 }, { "Render's Camp", 275, 53, 408, 143, 996, 998 }, { "Render's Valley", 594, 476, 817, 581, 997 }, { "Stonewatch", 571, 338, 677, 422, 70, 999 }, { "Stonewatch Falls", 652, 407, 814, 491, 71 }, { "Three Corners", 53, 424, 186, 555, 1002 } } },
      [1434] = { name = "Stranglethorn Vale", continent = 1415, note = { "Jungle from the edge of Duskwood to the sea, and the ruins of the troll empire all through it. The road runs south from the Rebel Camp in the north, past Nesingwary's hunting camp and the Horde's Grom'gol, all the way to Booty Bay at the southern tip.", "Booty Bay is the goblins' port, built into the cliffs of a drowned crater, and it is the safest town in the jungle as long as you pay. The rest belongs to whoever is strongest: the Bloodscalp and Skullsplitter trolls, the ogres of Mosh'Ogg, Colonel Kurzen's renegades, the Bloodsail pirates, and in the east, Zul'Gurub.", "The boat from Booty Bay goes to Ratchet. The tigers do not take boats, but they do swim." }, places = { { "Bal'lal Ruins", 270, 115, 320, 150, 123 }, { "Balia'mah Ruins", 390, 185, 445, 230, 127 }, { "Bloodsail Compound", 220, 325, 320, 390, 1739 }, { "Booty Bay", 220, 460, 305, 530, 35 }, { "Crystalvein Mine", 380, 310, 440, 365, 310 }, { "Grom'gol Base Camp", 285, 160, 350, 205, 117 }, { "Gurubashi Arena", 250, 255, 340, 335, 1741 }, { "Jaguero Isle", 350, 510, 430, 590, 297 }, { "Kal'ai Ruins", 320, 120, 370, 160, 125 }, { "Kurzen's Compound", 415, 35, 495, 90, 101 }, { "Lake Nazferiti", 375, 100, 435, 150, 37 }, { "Mistvale Valley", 320, 395, 355, 465, 1737 }, { "Mizjah Ruins", 350, 180, 390, 215, 129 }, { "Mosh'Ogg Ogre Mound", 455, 160, 535, 240, 105 }, { "Nek'mani Wellspring", 230, 385, 285, 450, 1738 }, { "Nesingwary's Expedition", 305, 60, 380, 115, 100 }, { "Rebel Camp", 335, 20, 415, 55, 99 }, { "Ruins of Aboraz", 375, 375, 420, 415, 311 }, { "Ruins of Jubuwal", 335, 325, 380, 365, 477 }, { "Ruins of Zul'Kunda", 220, 55, 300, 110, 102 }, { "Ruins of Zul'Mamwe", 435, 250, 500, 315, 103 }, { "The Vile Reef", 180, 135, 305, 235, 104 }, { "Venture Co. Base Camp", 420, 100, 465, 165, 1740 }, { "Wild Shore", 300, 505, 350, 555, 43 }, { "Ziata'jai Ruins", 385, 235, 430, 315, 128 }, { "Zul'Gurub", 525, 50, 675, 200, 19 }, { "Zuuldaia Ruins", 190, 80, 235, 120, 122 } } },
      [1435] = { name = "Swamp of Sorrows", continent = 1415, note = { "A drowned country of mist and mire, with Stonard, the Horde's town, in the middle of it. The road comes in from Deadwind Pass and runs south to the Blasted Lands.", "The Pool of Tears hides the sunken Temple of Atal'Hakkar under its water. The Lost Ones hold the Fallow Sanctuary in the east, and the few sane ones of their kind keep to the Harborage in the north. Crocolisks and murlocs keep to everywhere else.", "The swamp's name is fair. Leave it the way you came, and do not swim in it." }, places = { { "Fallow Sanctuary", 540, 60, 765, 240, 76 }, { "Itharius's Cave", 100, 350, 200, 490, 1777 }, { "Misty Reed Strand", 815, 75, 955, 630, 300 }, { "Misty Valley", 50, 190, 215, 290, 116 }, { "Pool of Tears", 620, 265, 805, 440, 74 }, { "Sorrowmurk", 775, 175, 905, 445, 1778 }, { "Splinterspear Junction", 150, 290, 340, 410, 1780 }, { "Stagalbog", 615, 455, 795, 600, 1797 }, { "Stonard", 370, 300, 585, 435, 75 }, { "The Harborage", 215, 190, 340, 290, 657 }, { "The Shifting Mire", 320, 160, 560, 305, 1798 } } },
      [1436] = { name = "Westfall", continent = 1415, note = { "Westfall was the breadbasket of Stormwind, and the fields are still there; the farmers mostly are not. The road from Elwynn crosses the river and runs south past empty farmsteads to Sentinel Hill, where the People's Militia keeps a tower and a fire for anyone who will help.", "South of the hill lies Moonbrook, which belongs to the Defias, and under Moonbrook the Deadmines, which belong to them more. The Jangolode Mine and the Gold Coast Quarry are theirs too. The harvest golems that should be bringing in the wheat walk the fields with no one at the controls.", "The lighthouse on the western shore is a good landmark. The coast below it is murloc country, and the murlocs are not interested in landmarks." }, places = { { "Alexston Farmstead", 325, 295, 440, 405, 219 }, { "Demont's Place", 260, 420, 365, 510, 921 }, { "Furlbrow's Pumpkin Farm", 465, 100, 555, 185, 109 }, { "Gold Coast Quarry", 255, 230, 375, 325, 113 }, { "Jangolode Mine", 405, 125, 490, 200, 111 }, { "Moonbrook", 390, 370, 495, 505, 20 }, { "Saldean's Farm", 505, 180, 605, 255, 107 }, { "Sentinel Hill", 515, 280, 605, 385, 108 }, { "The Dagger Hills", 380, 490, 560, 565, 920 }, { "The Dead Acre", 575, 370, 675, 450, 917 }, { "The Dust Plains", 560, 450, 710, 520, 922 }, { "The Jansen Stead", 520, 75, 615, 160, 916 }, { "The Molsen Farm", 395, 200, 505, 285, 918 }, { "Westfall Lighthouse", 260, 530, 380, 620, 115 } } },
      [1437] = { name = "Wetlands", continent = 1415, note = { "Wet is the word. The road from Loch Modan comes down through the pass of Dun Algaz into fens and marshes that never quite dry, and runs west to Menethil Harbor on the coast and north to the great bridge of Thandol Span.", "Menethil is the Alliance's port in the north: ships to Auberdine and to Theramore, and an inn full of people waiting for them. Inland, the Dragonmaw orcs hold the hills, the Dark Irons hold Dun Modr in the north, and in the east the gates of Grim Batol are shut and best left that way.", "The marshes are murloc and crocolisk country. Watch your footing, and watch the water you are footing in." }, places = { { "Angerfang Encampment", 400, 270, 550, 375, 1036 }, { "Black Channel Marsh", 125, 285, 275, 370, 1018 }, { "Bluegill Marsh", 120, 205, 265, 280, 1022 }, { "Direforge Hill", 550, 150, 665, 285, 1016 }, { "Dun Modr", 445, 80, 545, 145, 205 }, { "Grim Batol", 611, 230, 995, 614, 1037 }, { "Ironbeard's Tomb", 385, 150, 510, 265, 309 }, { "Menethil Harbor", 70, 345, 135, 415, 150 }, { "Mosshide Fen", 565, 305, 675, 425, 1020 }, { "Raptor Ridge", 665, 210, 780, 300, 1017 }, { "Saltspray Glen", 275, 95, 410, 230, 1023 }, { "Sundown Marsh", 140, 140, 325, 240, 1024 }, { "The Green Belt", 485, 170, 590, 320, 1025 }, { "Thelgen Rock", 505, 405, 625, 515, 1021 }, { "Whelgar's Excavation Site", 310, 295, 410, 360, 118 } } },
      [1438] = { name = "Teldrassil", continent = 1414, note = { "An island that is a tree, and a tree that is a world: the night elves' new home, grown over the sea. Shadowglen, where they train their young, lies in the north-east; the road runs west to Dolanaar and on to Darnassus in the branches.", "The forest is mostly kind. The Gnarlpine furbolgs have gone mad, the Webwood spiders hold their own corner, and the Ban'ethil barrow has things in it that the sentinels deal with quietly. Lakes and pools are everywhere, and clean.", "To leave, go down to Rut'theran Village at the roots by the portal in Darnassus; the boats go from there." }, places = { { "Ban'ethil Hollow", 420, 305, 510, 460, 736 }, { "Darnassus", 200, 290, 350, 480, 1657, 1660, 1662 }, { "Dolanaar", 495, 340, 610, 420, 186 }, { "Gnarlpine Hold", 400, 465, 480, 535, 261 }, { "Lake Al'Ameth", 495, 425, 660, 525, 259 }, { "Pools of Arlithrien", 375, 380, 435, 470, 478 }, { "Rut'theran Village", 550, 600, 565, 615, 702 }, { "Shadowglen", 535, 205, 660, 330, 188 }, { "Starbreeze Village", 605, 345, 710, 425, 260 }, { "The Oracle Glade", 350, 170, 410, 315, 264 }, { "Wellspring Lake", 415, 165, 525, 310, 266 } } },
      [1439] = { name = "Darkshore", continent = 1414, note = { "A long, misty coast of night elf ruins, across the water from Teldrassil. Auberdine is the only town, and the only port; its boats go to Rut'theran and to Menethil Harbor. The road runs south along the coast to Ashenvale.", "The ruins of Ameth'Aran, Bashal'Aran and Mathystra are full of ghosts and worse. The Dark Strand keep their tower at Althalaxx; the furbolgs of the Blackwood have gone wrong; and at Remtravel's dig the League is, as usual, in over its head.", "The sea fog comes in fast. When it does, stop walking until you can see the road." }, places = { { "Ameth'Aran", 395, 350, 460, 420, 447 }, { "Auberdine", 355, 255, 430, 330, 442 }, { "Bashal'Aran", 415, 215, 485, 270, 446 }, { "Cliffspring River", 485, 190, 590, 255, 456 }, { "Grove of the Ancients", 385, 475, 475, 555, 448 }, { "Remtravel's Excavation", 320, 540, 380, 600, 450 }, { "Ruins of Mathystra", 555, 60, 620, 160, 443 }, { "The Master's Glaive", 370, 555, 460, 630, 449 }, { "Tower of Althalaxx", 520, 145, 610, 205, 444 } } },
      [1440] = { name = "Ashenvale", continent = 1414, note = { "The ancient forest of the night elves, and the orcs' axes at its eastern edge. Astranaar is the elves' town, in the middle of the woods; the roads run from it north to Darkshore, west to Stonetalon, east to Azshara and south past the Mor'shan Rampart to the Barrens.", "The Warsong orcs log the east from their lumber camp, and the sentinels fight them for every tree. The Zoram Strand on the coast belongs to the naga; the furbolgs of Thistlefur have gone mad; and demons hold Felfire Hill and the canyon where Mannoroth fell.", "The forest is beautiful and very watchful. Do not cut anything you do not have to." }, places = { { "Astranaar", 310, 295, 435, 395, 415 }, { "Bough Shadow", 895, 200, 985, 285, 438 }, { "Fallen Sky Lake", 635, 505, 750, 590, 422 }, { "Felfire Hill", 750, 465, 915, 570, 434 }, { "Fire Scar Shrine", 235, 390, 300, 460, 417 }, { "Iris Lake", 430, 275, 500, 350, 424 }, { "Lake Falathim", 175, 230, 235, 310, 441 }, { "Maestra's Post", 250, 90, 335, 255, 413 }, { "Mystral Lake", 420, 430, 570, 550, 421 }, { "Night Run", 660, 340, 775, 450, 428 }, { "Raynewood Retreat", 560, 305, 660, 385, 426 }, { "Satyrnaar", 750, 290, 890, 355, 430 }, { "The Howling Vale", 500, 200, 625, 295, 419 }, { "The Ruins of Stardust", 295, 405, 375, 495, 418 }, { "The Shrine of Aessina", 175, 305, 270, 400, 416 }, { "The Zoram Strand", 45, 60, 215, 235, 414 }, { "Thistlefur Village", 335, 215, 405, 275, 2301 }, { "Warsong Lumber Camp", 855, 355, 970, 435, 437 } } },
      [1441] = { name = "Thousand Needles", continent = 1414, note = { "A canyon of stone spires below the Barrens, reached by the Great Lift at its northern rim. Freewind Post, the Horde's, stands on top of a needle with lifts of its own; the road runs down through the canyon to the Shimmering Flats in the east and on to Tanaris.", "The Grimtotem hold Darkcloud Pinnacle and its camps, the centaurs hold Splithoof Crag, and the harpies hold the Screeching Canyon, as advertised. On the salt flats, the gnomes and goblins race their machines at the Mirage Raceway, and are always looking for help.", "There is no shade on the flats and nothing to drink. Cross them early." }, places = { { "Camp E'thok", 65, 40, 260, 195, 480 }, { "Darkcloud Pinnacle", 305, 190, 395, 295, 2097 }, { "Freewind Post", 400, 300, 525, 405, 484 }, { "Highperch", 70, 150, 200, 305, 482 }, { "Splithoof Crag", 400, 225, 560, 325, 481 }, { "The Great Lift", 275, 115, 370, 185, 485 }, { "The Screeching Canyon", 225, 235, 390, 400, 483 }, { "The Shimmering Flats", 660, 325, 910, 650, 439 }, { "Windbreak Canyon", 550, 285, 700, 450, 2303 } } },
      [1442] = { name = "Stonetalon Mountains", continent = 1414, note = { "High peaks and old forests, and goblin saws in both. The night elves hold Stonetalon Peak in the north; the Horde holds Sun Rock Retreat in the middle of the range; the Darkspear have Malaka'jin in the south.", "The Venture Company is clear-cutting the forests and has already burned the Charred Vale to the ground. The road up from the Barrens is long and climbs through the Webwinder Path, which is named for exactly what you think.", "The air is thin up here and the drops are long. Stay on the trail." }, places = { { "Boulderslide Ravine", 600, 580, 700, 660, 2540 }, { "Camp Aparaje", 745, 600, 805, 635, 2538 }, { "Grimtotem Post", 700, 555, 815, 605, 2537 }, { "Malaka'jin", 695, 605, 765, 660, 2539 }, { "Mirkfallon Lake", 425, 220, 560, 325, 464 }, { "Sishir Canyon", 500, 465, 590, 535, 2541 }, { "Stonetalon Peak", 270, 30, 475, 150, 467 }, { "Sun Rock Retreat", 410, 345, 520, 435, 460 }, { "The Charred Vale", 245, 375, 395, 520, 465 }, { "Webwinder Path", 500, 315, 710, 600, 1076 }, { "Windshear Crag", 570, 240, 830, 435, 461 } } },
      [1443] = { name = "Desolace", continent = 1414, note = { "A grey, dead country of centaurs, bones and demons. Nijel's Point holds the north for the Alliance; Shadowprey Village sits on the western coast for the Horde. The road comes down from Stonetalon and runs south to Feralas.", "The five centaur clans fight each other across the middle of it, and the Kodo Graveyard lies between them, full of bones. The Burning Blade hold Thunder Axe Fortress, demons hold the Mannoroc Coven in the south, and the naga hold the coast.", "Nothing grows here and nothing is buried for long. Keep moving." }, places = { { "Ethel Rethor", 345, 135, 475, 275, 2405 }, { "Gelkis Village", 320, 540, 450, 650, 606 }, { "Kodo Graveyard", 435, 325, 580, 450, 596 }, { "Kolkar Village", 695, 275, 795, 375, 609 }, { "Kormek's Hut", 590, 230, 700, 310, 2407 }, { "Magram Village", 650, 425, 775, 550, 604 }, { "Mannoroc Coven", 455, 470, 615, 590, 602 }, { "Nijel's Point", 600, 25, 700, 100, 608 }, { "Ranazjar Isle", 255, 25, 325, 85, 2406 }, { "Sargeron", 695, 95, 825, 210, 603 }, { "Shadowbreak Ravine", 760, 485, 850, 575, 2198 }, { "Shadowprey Village", 195, 420, 315, 520, 2408 }, { "Tethris Aran", 495, 50, 595, 115, 2404 }, { "Thunder Axe Fortress", 490, 150, 600, 225, 599 }, { "Valley of Spears", 250, 255, 415, 440, 607 } } },
      [1444] = { name = "Feralas", continent = 1414, note = { "Giant trees, steady rain and the ruins of the Highborne. Feathermoon Stronghold sits on Sardor Isle off the western coast, for the night elves; Camp Mojache holds the east for the Horde. The road runs from Desolace in the north to the Thousand Needles in the east.", "The Gordok ogres hold the ruins of Dire Maul, once the elven city of Eldre'Thalas. Yetis live in the Feral Scar Vale, the Grimtotem have their compound, and around the great tree of Dream Bough the green dragons keep their troubled watch.", "The forest is wet enough to grow moss on a slow traveller. Do not be a slow traveller." }, places = { { "Camp Mojache", 715, 250, 795, 315, 1099 }, { "Dire Maul", 525, 235, 655, 325, 2577 }, { "Dream Bough", 490, 40, 540, 95, 1111 }, { "Feral Scar Vale", 510, 350, 580, 410, 1105 }, { "Frayfeather Highlands", 505, 415, 570, 535, 1106 }, { "Gordunni Outpost", 725, 175, 825, 240, 1103 }, { "Grimtotem Compound", 650, 220, 710, 320, 1100 }, { "Isle of Dread", 225, 410, 370, 645, 1121 }, { "Lower Wilds", 800, 240, 925, 335, 1137 }, { "Oneiros", 520, 95, 575, 130, 1113 }, { "Ruins of Isildien", 565, 375, 665, 520, 2522 }, { "Ruins of Ravenwind", 360, 45, 435, 100, 1114 }, { "Sardor Isle", 235, 280, 370, 390, 1120 }, { "The Forgotten Coast", 430, 275, 500, 555, 1108 }, { "The Twin Colossals", 395, 100, 550, 240, 1119 }, { "The Writhing Deep", 645, 340, 815, 475, 1101 } } },
      [1445] = { name = "Dustwallow Marsh", continent = 1414, note = { "A swamp of mist and mud on Kalimdor's eastern coast. Theramore Isle, Lady Proudmoore's city, sits offshore with a harbour and ships to Menethil; Brackenwall Village, where the Stonemaul ogres keep faith with the Horde, sits in the north-west marsh.", "The black dragons have the Wyrmbog in the south, and Onyxia her lair beneath it. Raptors, crocolisks and worse fill the rest, and the road in from the Barrens is wet the whole way.", "The fog lies thick at dawn and dusk. A lantern helps; so does a guide." }, places = { { "Alcaz Island", 695, 55, 820, 180, 2079 }, { "Brackenwall Village", 305, 70, 435, 235, 496, 499, 507 }, { "The Den of Flame", 315, 345, 425, 475, 509, 508, 498, 510 }, { "The Quagmire", 320, 240, 570, 410, 2302, 501, 517 }, { "Theramore Isle", 615, 280, 750, 405, 513, 503 }, { "Witch Hill", 445, 60, 635, 245, 502, 518, 504, 516 }, { "Wyrmbog", 440, 435, 615, 570, 511, 517 } } },
      [1446] = { name = "Tanaris", continent = 1414, note = { "The great desert of the south, and Gadgetzan, the goblins' town, in the middle of it: neutral, walled and guarded by bruisers who will break up any fight inside the walls. The road comes from the Thousand Needles; Steamwheedle Port lies on the eastern coast.", "The Sandfury trolls hold Zul'Farrak in the north-west, the pirates hold Lost Rigger Cove, the ogres hold Dunemaul, and the silithid dig in the south. In the eastern mountains, the bronze dragons guard the Caverns of Time, and the Valley of the Watchers hides something older.", "Water is sold by the cup in Gadgetzan. Buy more than you think you need." }, places = { { "Abyssal Sands", 410, 240, 505, 330, 1939 }, { "Broken Pillar", 500, 275, 565, 335, 1938 }, { "Caverns of Time", 595, 295, 690, 365, 2300 }, { "Dunemaul Compound", 380, 335, 460, 415, 983 }, { "Eastmoon Ruins", 435, 410, 500, 460, 984 }, { "Gadgetzan", 460, 140, 565, 225, 976 }, { "Land's End Beach", 480, 565, 620, 660, 987 }, { "Lost Rigger Cove", 675, 255, 760, 375, 1336 }, { "Noonshade Ruins", 570, 140, 630, 190, 1937 }, { "Sandsorrow Watch", 365, 155, 435, 225, 979 }, { "Southbreak Shore", 570, 365, 680, 430, 1940 }, { "Southmoon Ruins", 365, 445, 440, 510, 992 }, { "Steamwheedle Port", 630, 110, 710, 175, 977 }, { "The Gaping Chasm", 490, 415, 600, 530, 981 }, { "The Noxious Lair", 310, 255, 385, 355, 982 }, { "Thistleshrub Valley", 245, 360, 370, 475, 980 }, { "Valley of the Watchers", 330, 490, 410, 585, 990 }, { "Waterspring Field", 550, 210, 645, 295, 985 }, { "Zalashji's Den", 640, 190, 700, 255, 986 }, { "Zul'Farrak", 300, 25, 450, 145, 978 } } },
      [1447] = { name = "Azshara", continent = 1414, note = { "The queen's land, on the shore of the sea that swallowed her. It is autumn here all year round, among the ruins of the Highborne. The road comes in from Ashenvale; the Horde holds Valormok in the west.", "Naga hold the ruins along the coast and the temple of Arkkoran; satyrs hold their encampments in the hills; blood elves dig at the Highborne's ruins for their lost magic; and the blue dragon Azuregos guards the southern hills. The Timbermaw furbolgs keep their hold in the north, and the tunnels that lead to Winterspring and Moonglade.", "Every ruin here is older than any kingdom you can name. Touch nothing you cannot carry away." }, places = { { "Bay of Storms", 505, 255, 675, 475, 1227 }, { "Bitter Reaches", 685, 80, 850, 180, 2497 }, { "Forlorn Ridge", 220, 425, 370, 530, 1233 }, { "Haldarr Encampment", 165, 370, 250, 435, 1236 }, { "Jagged Reef", 400, 35, 880, 115, 1230 }, { "Lake Mennar", 375, 490, 490, 580, 1234 }, { "Legashi Encampment", 495, 90, 665, 150, 1219 }, { "Ravencrest Monument", 660, 535, 755, 600, 1232 }, { "Ruins of Eldarath", 305, 310, 430, 415, 1221 }, { "Shadowsong Shrine", 125, 455, 225, 545, 1235 }, { "Southridge Beach", 440, 420, 730, 540, 1231 }, { "Temple of Arkkoran", 715, 225, 820, 325, 1226 }, { "Thalassian Base Camp", 535, 160, 685, 225, 1220 }, { "The Ruined Reaches", 440, 580, 725, 645, 1256 }, { "The Shattered Strand", 430, 245, 485, 370, 1228 }, { "Timbermaw Hold", 250, 106, 506, 394, 1769 }, { "Tower of Eldara", 850, 160, 920, 245, 1229 }, { "Ursolan", 430, 150, 510, 230, 1225 }, { "Valormok", 165, 310, 265, 365, 1237 } } },
      [1448] = { name = "Felwood", continent = 1414, note = { "A forest poisoned by demons, north of Ashenvale. The trees are dying, the water burns and the animals have gone mad. Talonbranch Glade holds the north for the night elves, Bloodvenom Post the south for the Horde, and the Cenarion Circle keeps the Emerald Sanctuary in between.", "The Shadow Council keeps Jaedenar, the satyrs keep Jadefire, and the furbolgs of the Deadwood have lost their minds. The road runs north through the length of it to the Timbermaw tunnel to Winterspring.", "Drink nothing that grows here. The green glow is not a good sign." }, places = { { "Bloodvenom Falls", 360, 295, 490, 355, 1765 }, { "Deadwood Village", 450, 580, 535, 640, 1761 }, { "Emerald Sanctuary", 470, 505, 565, 560, 2479 }, { "Felpaw Village", 585, 35, 685, 110, 1762 }, { "Irontree Woods", 455, 120, 550, 195, 1767 }, { "Jadefire Glen", 370, 510, 455, 595, 2480 }, { "Jadefire Run", 370, 85, 455, 155, 2618 }, { "Jaedenar", 300, 375, 430, 425, 1763 }, { "Morlos'Aran", 540, 560, 615, 615, 2478 }, { "Ruins of Constellas", 335, 425, 425, 500, 2481 }, { "Shatter Scar Vale", 370, 175, 475, 295, 1766 }, { "Talonbranch Glade ", 585, 130, 660, 195, 1998 } } },
      [1449] = { name = "Un'Goro Crater", continent = 1414, note = { "A crater in the south where the world has kept a corner of its youth: jungle, hot springs, tar pits and a volcano, and beasts that should not still be alive. The way in is a long path down from Tanaris; the way to Silithus leaves from the north-west.", "Marshal's Refuge, on the northern rim, is the only camp and the only safe sleep. Everything else is the devilsaurs' and the raptors', and the silithid in the Slithering Scar. Fire Plume Ridge is hot enough to cook on and steep enough to fall from.", "Strange crystals grow everywhere in the crater. Nobody knows what they are. I have filled three notebooks with guesses." }, places = { { "Fire Plume Ridge", 415, 250, 595, 415, 537 }, { "Golakka Hot Springs", 215, 235, 390, 435, 543 }, { "Ironstone Plateau", 625, 145, 825, 320, 1943 }, { "Lakkari Tar Pits", 355, 25, 660, 250, 538 }, { "Terror Run", 300, 415, 445, 575, 539 }, { "The Marshlands", 615, 305, 780, 540, 1942 }, { "The Slithering Scar", 440, 470, 595, 600, 540 } } },
      [1450] = { name = "Moonglade", continent = 1414, note = { "The druids' sacred valley, around Lake Elune'ara. The town of Nighthaven sits on its shore, and Keeper Remulos keeps his shrine nearby. Druids of every race come and go by their own magic; the rest of us come through the Timbermaw tunnel from Felwood.", "Nobody fights here. Nobody would dare.", "In the barrow dens of the valley, Malfurion Stormrage sleeps. The druids will not show you the way, and you should not ask." }, places = { { "Moonglade", 244, 89, 820, 601, 493, 656, 2362, 2361 } } },
      [1451] = { name = "Silithus", continent = 1414, note = { "The insect desert, at the far south-west of Kalimdor. Cenarion Hold, the druids', is the only camp, and it is on a war footing. The way in is from Un'Goro.", "The silithid hives fill the desert, the Twilight's Hammer camp in the wastes and calls up things from the elements, and in the south the Scarab Wall holds back Ahn'Qiraj, as it has for a thousand years. Southwind Village is a ruin.", "Sand gets into everything here, including the instruments. Check your compass against the sun twice a day." }, places = { { "Hive'Ashi", 385, 100, 515, 225, 2742 }, { "Hive'Regal", 490, 425, 655, 650, 2744 }, { "Hive'Zora", 165, 310, 330, 470, 2743 }, { "Southwind Village", 585, 315, 665, 395, 2738 }, { "The Crystal Vale", 150, 50, 315, 185, 2740 }, { "The Scarab Wall", 220, 615, 360, 655, 2737 }, { "Twilight Base Camp", 343, 196, 663, 452, 2739 } } },
      [1452] = { name = "Winterspring", continent = 1414, note = { "Snow, the goblins of Everlook, and the Highborne's curse. The way in is the Timbermaw tunnel from Felwood; Everlook, the goblins' trading town, is the only real roof, and it is neutral and pricey.", "Starfall Village keeps the night elves' watch in the west. The blue dragons hold the caves of Mazthoril, the Winterfall furbolgs have gone wrong, yetis fill the Ice Thistle Hills, and demons haunt Darkwhisper Gorge in the far south.", "The hot springs are the only warmth outside Everlook. The frostsabers know this too." }, places = { { "Darkwhisper Gorge", 490, 500, 670, 610, 2256, 16005 }, { "Everlook", 565, 220, 655, 285, 2255 }, { "Frostfire Hot Springs", 275, 220, 395, 270, 2246 }, { "Frostsaber Rock", 440, 55, 550, 115, 2241 }, { "Frostwhisper Gorge", 575, 420, 665, 495, 2249 }, { "Ice Thistle Hills", 650, 265, 715, 345, 2247 }, { "Lake Kel'Theril", 485, 250, 580, 330, 2251 }, { "Mazthoril", 555, 360, 615, 415, 2245 }, { "Owl Wing Thicket", 620, 380, 690, 445, 2250 }, { "Starfall Village", 445, 160, 550, 220, 2253 }, { "The Hidden Grove", 600, 80, 695, 150, 2242 }, { "Timbermaw Post", 365, 270, 440, 310, 2243 }, { "Winterfall Village", 650, 220, 720, 270, 2244 } } },
      [1453] = { name = "Stormwind City", continent = 1415, note = { "The white city, rebuilt from its ashes and guarded by more walls than it can afford. Every road in Elwynn leads to its gate, past the statues of its heroes.", "Everything a traveller needs is here: the bank, the auction house, trainers of every craft and the cathedral. The Deeprun Tram runs under the mountains to Ironforge, and the gryphons fly from the Trade District.", "The Stockade holds the city's worst prisoners, or did." }, places = {  } },
      [1454] = { name = "Orgrimmar", continent = 1414, note = { "The Horde's capital, a fortress in a canyon of red rock, named for the Warchief who freed the orcs. The gate faces Durotar to the south.", "The bank, the auction house and every trainer are inside; Thrall keeps Grommash Hold, and the Cleft of Shadow keeps its own secrets. The zeppelins to Undercity and to Grom'gol leave from a tower outside the walls, and the wind riders fly from the tower in the city.", "It is louder than Ironforge, which I did not think possible." }, places = {  } },
      [1455] = { name = "Ironforge", continent = 1415, note = { "The city inside the mountain, around the Great Forge. The gate faces Dun Morogh; inside, it is warm, loud and full of dwarves, which is as it should be.", "The bank and the auction house share the Commons; the Hall of Explorers keeps the League's library and its collection, and the Mystic Ward its mages. The Deeprun Tram runs south under the mountains to Stormwind, and the gryphons fly from the Great Forge's upper level.", "Do not touch the anvils. The smiths will know." }, places = {  } },
      [1456] = { name = "Thunder Bluff", continent = 1414, note = { "The tauren's city on the mesas of northern Mulgore, joined by rope bridges and reached by great lifts from the plain below.", "Each rise has its purpose: Elder Rise for the elders and the druids, Spirit Rise for the shamans and the priests, Hunter Rise for the hunters and the warriors. The bank and the auction house are on the central rise, and the wind riders fly from the tower.", "The bridges sway. Do not look down, and do not run." }, places = {  } },
      [1457] = { name = "Darnassus", continent = 1414, note = { "The night elves' city in the branches of Teldrassil, all moonlight, water and sentinels. The Temple of the Moon is its heart.", "Trainers, a bank and an auction house are here, quieter than any other city's. Darnassus is reached from Dolanaar by the road, or from Rut'theran Village by the portal at the roots.", "It is the only city where I have heard silence. Keep it." }, places = {  } },
      [1458] = { name = "Undercity", continent = 1415, note = { "The Forsaken's city, built in the crypts and sewers under the ruins of Lordaeron's capital. Lifts come down from the ruined throne room above.", "The bank, the auction house and the trainers are here, along with the Royal Apothecary Society, which makes things in its quarter that I will not describe. The canals run green.", "It is dark, it is quiet, and everything in it is watching. The zeppelins leave from a tower outside the ruins." }, places = {  } },
      [2482] = { name = "Mount Hyjal", continent = 1414, places = { { "Cradle of Tranquility", 267, 227, 410, 338, 17145 }, { "Dae'gun", 451, 170, 640, 328, 16866 }, { "Elderwild", 80, 266, 198, 400, 16848 }, { "Felblood Scar", 387, 440, 538, 586, 17050 }, { "Malorne's Retreat", 207, 423, 371, 520, 17144 }, { "Mourning's Rest", 191, 300, 293, 404, 16868 }, { "Shrine of Aviana", 437, 355, 578, 435, 16867 }, { "Summit of Eternity", 677, 125, 895, 345, 16849 }, { "Tainted Foothills", 592, 404, 822, 571, 16853 } } },
